(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{}).gen={"1":{"1":"В начале сотворил Бог небо и землю.","2":"Земля была пуста и пустынна, тьма была над пучиной, и дух Божий веял над водами.","3":"И сказал Бог: «Да будет свет». И появился свет.","4":"Бог увидел, как хорош свет, и отделил его от тьмы,","5":"дал свету имя «день», а тьме – имя «ночь». Настал вечер, настало утро – первый день.","6":"И сказал Бог: «Пусть средь воды будет свод, разделяющий воды надвое». И стало так.","7":"Бог создал свод, и отделил воды под сводом от вод над сводом,","8":"и дал своду имя «небо». Настал вечер, настало утро – второй день.","9":"И сказал Бог: «Пусть воды, что под небом, соберутся вместе и покажется суша». И стало так. Воды, что под небом, собрались вместе – и показалась суша.","10":"Бог дал суше имя «земля», а собравшимся водам – имя «моря». И увидел Бог, как это хорошо.","11":"И сказал Бог: «Пусть земля порастет растениями: травами, которые будут давать семена, и деревьями разных видов, которые будут давать плоды с семенами». И стало так.","12":"Земля породила растения: травы разных видов, дающие семена, и деревья разных видов, приносящие плоды с семенами. И увидел Бог, как это хорошо.","13":"Настал вечер, настало утро – третий день.","14":"И сказал Бог: «Пусть будут светила на своде небесном, чтобы отделять день от ночи, указывать сроки, отмерять дни и года.","15":"Пусть светят они с небесного свода и освещают землю». И стало так.","16":"Бог создал два больших светила (большее – чтобы оно управляло днями, меньшее – чтобы оно управляло ночами) и звезды.","17":"Бог поместил их на своде небесном, чтобы они освещали землю,","18":"управляли днями и ночами и отделяли свет от тьмы. И увидел Бог, как это хорошо.","19":"Настал вечер, настало утро – четвертый день.","20":"И сказал Бог: «Пусть вода кишит живыми существами. А над землей, по своду небесному, пусть летают птицы».","21":"И Бог сотворил огромных чудищ морских, и разные виды живых существ, которые снуют и кишат в воде, и разные виды крылатых птиц. И увидел Бог, как это хорошо,","22":"и благословил их: «Будьте плодовиты и многочисленны, заселяйте воды морей. А на земле пусть будет много птиц».","23":"Настал вечер, настало утро – пятый день.","24":"И сказал Бог: «Пусть земля породит разные виды живых существ: скот, мелкую живность и разные виды зверей». И стало так.","25":"Бог создал разные виды зверей, скота и всякой живности, которая снует по земле. И увидел Бог, как это хорошо.","26":"И сказал Бог: «Создадим человека – Наш образ и Наше подобие – чтобы он господствовал над рыбами морскими, и над птицами небесными, и над скотом, и над всею землею, и над всею живностью, которая снует по земле».","27":"Бог сотворил человека, образ Свой, Божий образ Он сотворил, мужчину и женщину сотворил.","28":"И благословил их Бог такими словами: «Будьте плодовиты и многочисленны, заселяйте землю и покоряйте ее. Господствуйте над рыбами морскими, и над птицами небесными, и над всеми животными земли».","29":"И сказал Бог: «Я отдаю вам в пищу все травы с семенами, какие есть на земле, и все деревья, приносящие плоды с семенами.","30":"А зверям земным, и птицам небесным, и живности земной – всем, в ком дышит жизнь, – Я отдаю в пищу зелень растений». И стало так.","31":"Бог оглядел Свое творение – все оно было очень хорошо. Настал вечер, настало утро – шестой день."},"2":{"1":"Так были созданы небо и земля и весь строй творений небесных и земных.","2":"В седьмой день Бог завершил работу Свою. В седьмой день, окончив Свой труд, Он пребывал в покое.","3":"Бог благословил седьмой день и сделал его священным, ибо в этот день, окончив труд творения, Он пребывал в покое.","4":"Вот рассказ про небо и землю в пору их сотворения. Когда Господь Бог создал землю и небо,","5":"то не было на земле ни куста, ни травинки. Ведь Господь Бог не посылал еще на землю дождя и не было людей, чтобы ее возделывать.","6":"Лишь поток, что поднимался из недр, орошал землю.","7":"Создал Господь Бог человека из пыли земной, вдохнул в его ноздри дыхание жизни, и человек ожил.","8":"В Эдеме, на востоке, Господь Бог насадил сад и поселил в нем человека, которого создал.","9":"Господь Бог вырастил там всевозможные деревья, приятные взору и с хорошими плодами, и дерево жизни, посреди сада, и дерево познания добра и зла.","10":"Из Эдема вытекает река; она орошает сад, а далее разделяется на четыре рукава.","11":"Один из них называется Пишон, он огибает страну Хавила, где есть золото","12":"(хорошее золото в той стране, есть там и благовонная смола, и драгоценный камень шохам).","13":"Вторая река называется Гихон и огибает страну Куш.","14":"Третья река называется Тигр, она течет к востоку от Ашшура. Четвертая река – Евфрат.","15":"Поселив человека в Эдемском саду, чтобы он возделывал этот сад и берег его,","16":"Господь Бог дал человеку такой наказ: «Ты можешь есть плоды любого дерева в этом саду,","17":"не ешь только плоды с дерева познания добра и зла. Если съешь – в тот же день умрешь».","18":"Господь Бог сказал: «Плохо человеку быть одному. Сотворю – ка Я для него помощника, ему под стать».","19":"Господь Бог создал из земли всевозможных зверей и птиц и привел к человеку, посмотреть, как тот назовет их. Какое имя даст человек животному – так оно и будет называться.","20":"Всем домашним животным, всем птицам, всем зверям дал человек имена – но не нашел среди них помощника себе под стать.","21":"Тогда Господь Бог погрузил человека в глубокий сон и вынул у него ребро, а место, где оно было, закрыл плотью.","22":"Из ребра Господь Бог создал женщину, привел ее к человеку,","23":"и человек сказал: «Вот она, кость от кости моей, плоть от плоти моей. Женщиной будет зваться она, ибо взята из мужчины».","24":"(Вот почему мужчина оставляет отца и мать, и соединяется с женою, и становится с нею единой плотью.)","25":"Оба, и мужчина и женщина, были наги, но не стыдились."},"3":{"1":"Змей был самым хитрым из всех зверей, созданных Господом Богом. Он спросил у женщины: «Правда, что Бог не разрешает вам есть никаких плодов в этом саду?» –","2":"«Нам можно есть плоды, – ответила женщина. –","3":"Вот только про дерево, которое стоит посреди сада, Бог сказал, чтобы мы его плодов не ели и даже не прикасались к ним, а то умрем!» –","4":"«Не умрете, – сказал змей. –","5":"Но Бог знает, что когда вы съедите их, то прозреете и сами станете как боги – познаете добро и зло!»","6":"Женщина увидела, что плоды этого дерева годятся в пищу, приятны взору и сулят знание. Она сорвала плод и съела, и мужу дала плод, чтобы он съел.","7":"Они прозрели, увидели свою наготу и сделали себе набедренные повязки из листьев смоковницы.","8":"«Когда повеял вечерний ветер, они услышали, как по саду идет Господь Бог, и спрятались за деревьями.","9":"«Где ты?» – позвал человека Господь Бог.","10":"Тот ответил: «Я услышал, как Ты идешь по саду. Я испугался своей наготы, и спрятался». –","11":"«Кто сказал тебе про твою наготу? – спросил Господь Бог. – Ты ел плоды дерева, с которого Я запретил тебе есть?»","12":"Человек ответил: «Женщина, которую Ты мне дал, – она дала мне эти плоды, и я ел их». –","13":"«Зачем ты это сделала?» – спросил Господь Бог у женщины. Та ответила: «Змей меня обманул, и я ела».","14":"И Господь Бог сказал змею: «Ты проклят за то, что сделал: изгой средь зверей и скота, ты будешь ползать на брюхе и пылью питаться всю жизнь.","15":"Тебя и женщину Я сделаю врагами, и дети ваши будут врагами друг другу: сын ее голову тебе разбивает, а ты жалишь его в пяту».","16":"Женщине Господь Бог сказал: «Мучительной Я сделаю беременность твою, в муках будешь рожать детей. Мужа своего ты будешь вожделеть: муж будет господином твоим».","17":"А человеку Господь Бог сказал: «Послушав женщину, ты съел плод, который Я запретил тебе есть! Ныне проклята из – за тебя земля: в муках будешь ее плоды добывать, день за днем, всю твою жизнь.","18":"Колючки и репей она тебе произрастит, полевою травою питаться будешь","19":"и в поте лица добывать свой хлеб. И вернешься ты в землю, из которой был взят: ты – пыль и вновь обратишься в пыль».","20":"Человек – Адам – дал своей жене имя Ева, ибо она стала праматерью всех живущих.","21":"Господь Бог сделал одежду из кож и одел человека и его жену.","22":"И сказал Господь Бог: «Человек стал как один из Нас – познал добро и зло! Не сорвал бы он еще и плод дерева жизни, чтобы, съев его, стать бессмертным!»","23":"И Господь Бог изгнал человека из Эдемского сада – пусть возделывает землю, из которой был взят.","24":"Изгнал человека, а у Эдемского сада, на востоке, поставил стражу – херувимов и огненный меч, во все стороны разящий, чтобы они охраняли дорогу к дереву жизни."},"4":{"1":"Адам познал свою жену, Еву, и она забеременела. Она родила сына, Каина, и сказала: «Человека обрела я с помощью Господней!»","2":"Потом она родила Авеля, брата Каина. Авель пас овец, а Каин возделывал землю.","3":"Через какое – то время Каин принес в дар Господу плоды земли,","4":"а Авель – жир ягнят из первого приплода.","5":"Дар Авеля был угоден Господу, а дар Каина неугоден. Гнев омрачил лицо Каина.","6":"«Отчего ты разгневался? – спросил Господь у Каина. – Отчего омрачилось твое лицо?","7":"Если делаешь добро – подними голову. А если нет, то у порога грех таится. Он тебя вожделеет, ты будешь владыкой его».","8":"Каин сказал своему брату Авелю: «Выйдем в поле». В поле Каин бросился на Авеля и убил его.","9":"«Где твой брат Авель?» – спросил Господь. Каин ответил: «Не знаю. Разве я сторож брату моему?» –","10":"«Что ты наделал? – сказал Господь. – Кровь твоего брата, пролившаяся на землю, взывает ко Мне.","11":"Ты проклят землей, которую ты напоил кровью брата,","12":"и впредь, сколько бы ты ни возделывал эту землю, она уже не даст тебе своей силы. Отныне ты изгнанник и скиталец». –","13":"«Эта кара тяжела, – сказал Каин, – мне не вынести.","14":"Ты меня гонишь с земли, скроюсь я от Тебя. Изгнанник я и скиталец – любой меня может убить».","15":"Но Господь сказал: «Кто убьет Каина, тому будет отомщено семикратно». И Господь отметил Каина особым знаком, чтобы встречные не смели его убить.","16":"Каин ушел от Господа прочь и поселился в стране Нод, к востоку от Эдема.","17":"Каин познал свою жену и она забеременела. Она родила сына – Еноха. Каин в ту пору строил город и назвал его Енох, по имени сына.","18":"У Еноха родился сын Ирад, у Ирада – Мехияэл, у Мехияэла – Метушаэл, у Метуша – эла – Ламех.","19":"Ламех взял себе двух жен: одну звали Ада, а другую Цилла .","20":"У Ады родился сын Явал, и от него произошли те, кто живет в шатрах и пасет скот,","21":"а от его брата Ювала – все, кто играет на лире и свирели.","22":"У Циллы родился сын Тувал – Каин – кузнец, от которого произошли все, кто кует медь и железо. Сестрой Тувал – Каина была Наама .","23":"Ламех сказал своим женам: «Слушайте меня, Ада и Цилла! Слушайте, жены, что я скажу! Если ранит меня мужчина – убью! И если мальчишка ударит – убью!","24":"За Каина будет отомщено семикратно, а за Ламеха – семьдесят раз и семикратно!»","25":"Адам вновь познал свою жену. Она родила сына и назвала его Шет, что означало: «Бог дал мне новое дитя вместо Авеля, убитого Каином».","26":"У Шета был сын, которого он назвал Энош. С тех пор люди и начали призывать имя Господне."},"5":{"1":"Вот книга про род Адама. Когда Бог сотворил человека, создал Он подобие Божье.","2":"Он мужчину и женщину сотворил, благословил и, сотворив их, дал им имя «человек».","3":"Когда Адаму было сто тридцать лет, у него родился сын – его образ и подобие. Адам дал ему имя Шет.","4":"После рождения Шета Адам жил восемьсот лет; у него были еще сыновья и дочери.","5":"Прожив девятьсот тридцать лет, Адам умер.","6":"Когда Шету было сто пять лет, у него родился сын Энош.","7":"После рождения Эноша Шет жил восемьсот семь лет; у него были еще сыновья и дочери.","8":"Прожив девятьсот двенадцать лет, Шет умер.","9":"Когда Эношу было девяносто лет, у него родился сын Кенан.","10":"После рождения Кенана Энош жил восемьсот пятнадцать лет; у него были еще сыновья и дочери.","11":"Прожив девятьсот пять лет, Энош умер.","12":"Когда Кенану было семьдесят лет, у него родился сын Махалалэл.","13":"После рождения Махалалэла Кенан жил восемьсот сорок лет; у него были еще сыновья и дочери.","14":"Прожив девятьсот десять лет, Кенан умер.","15":"Когда Махалалэлу было шестьдесят пять лет, у него родился сын Иеред.","16":"После рождения Иереда Махалалэл жил восемьсот тридцать лет; у него были еще сыновья и дочери.","17":"Прожив восемьсот девяносто пять лет, Махалалэл умер.","18":"Когда Иереду было сто шестьдесят два года, у него родился сын Енох.","19":"После рождения Еноха Иеред жил восемьсот лет; у него были еще сыновья и дочери.","20":"Прожив девятьсот шестьдесят два года, Иеред умер.","21":"Когда Еноху было шестьдесят пять лет, у него родился сын Метушелах.","22":"После рождения Метушелаха Енох жил триста лет, его жизнь шла с Богом, у него были еще сыновья и дочери.","23":"Триста шестьдесят пять лет прожил Енох,","24":"и его жизнь шла с Богом. И не стало Еноха: Бог взял его к Себе.","25":"Когда Метушелаху было сто восемьдесят семь лет, у него родился сын Ламех.","26":"После рождения Ламеха Метушелах жил семьсот восемьдесят два года; у него были еще сыновья и дочери.","27":"Прожив девятьсот шестьдесят девять лет, Метушелах умер.","28":"Когда Ламеху было сто восемьдесят два года, у него родился сын.","29":"Ламех дал ему имя Ной и сказал: «Он принесет нам утешение в нашей работе, в наших трудах на земле, проклятой Господом».","30":"После рождения Ноя Ламех жил пятьсот девяносто пять лет; у него были еще сыновья и дочери.","31":"Прожив семьсот семьдесят семь лет, Ламех умер.","32":"Когда Ною было пятьсот лет, у него родились сыновья: Сим, Хам и Яфет."},"6":{"1":"Людей на земле становилось все больше. У них рождались дочери,","2":"и, видя красоту дочерей человеческих, сыны Божьи брали их себе в жены, кому какая понравится.","3":"И сказал Господь: «Мое дыхание в человеке – не навсегда. Он всего лишь плоть, и пусть срок его жизни будет сто двадцать лет».","4":"В ту пору (как и позже) были на земле исполины, ибо сыны Божьи приходили к дочерям человеческим, а те рожали от них детей. Богатыри былых времен, они прославили свое имя.","5":"И увидел Господь, как много зла на земле от людей: все их мысли непрестанно устремлены к злу.","6":"Пожалел Он, что создал на земле человека, горечью наполнилось Его сердце,","7":"и Он сказал: «Я смету с лица земли всех людей, которых сотворил, а вместе с ними и скот, и зверей, и птиц. Я жалею, что создал их».","8":"Один лишь Ной был угоден Господу.","9":"Вот рассказ про род Ноя. Среди людей того времени один только Ной был праведен и непорочен; его жизнь шла с Богом.","10":"У Ноя было три сына: Сим, Хам и Яфет.","11":"Омерзительна стала земля для Бога: зло ее переполнило.","12":"Бог увидел, как мерзостна стала земля, какими мерзкими путями идут все.","13":"И Бог сказал Ною: «Я покончу со всеми, кто живет на земле: она переполнена их злодеяниями. Я уничтожу их всех, а с ними и всю землю.","14":"Но ты сделай себе из дерева гофер ковчег и устрой в нем отсеки, а изнутри и снаружи обмажь его смолой.","15":"Пусть он будет в длину триста локтей, в ширину – пятьдесят, а в высоту – тридцать.","16":"Сделай крышу – так, чтобы сверху она выступала на один локоть. Сбоку сделай дверь. Пусть будут в ковчеге первый ярус, второй и третий.","17":"Я затоплю землю и уничтожу на ней всех, в ком есть дыхание жизни. Все, кто живет на земле, погибнут.","18":"Но с тобою будет у Меня договор, что Я беру тебя под свое покровительство. Ты войдешь в ковчег – с сыновьями, женой и женами сыновей –","19":"и возьмешь с собой по паре из всех живых существ, самца и самку, чтобы и они вместе с тобой уцелели.","20":"По паре от каждого вида птиц, скота и всякой живности земной пусть войдет с тобою в ковчег, чтобы уцелеть.","21":"Возьми с собой всякой пищи – сделай запасы себе и им».","22":"Ной сделал все, что повелел ему Бог."},"7":{"1":"Господь сказал Ною: «Войди в ковчег и возьми с собой семью. Я вижу, что из всех ныне живущих ты один праведен предо Мною.","2":"Возьми с собой по семь пар, самцов и самок, от всех видов чистых животных, и по паре, самца и самку, от всех видов нечистых животных,","3":"и по семь пар, самцов и самок, от всех видов птиц небесных. Пусть сохранится на земле их род.","4":"Через семь дней Я пошлю на землю дождь – он будет литься сорок дней и сорок ночей – и Я смету с лица земли всех, кого Я создал».","5":"Ной выполнил все, что повелел Господь.","6":"Когда Ною было шестьсот лет, начался потоп.","7":"Ной укрылся от потопа в ковчеге, вместе с сыновьями, женой и женами сыновей,","8":"а из всех видов скота, чистого и нечистого, и птиц, и всякой живности земной","9":"к нему в ковчег пришло по паре, самец и самка, – как повелел ему Бог.","10":"Семь дней минуло, и начался потоп.","11":"В шестисотый год жизни Ноя, во второй месяц года, в семнадцатый день месяца отверзлись жерла великой пучины, распахнулись небесные створы –","12":"и лился на землю дождь сорок дней и сорок ночей.","13":"В этот день Ной вошел в ковчег, вместе с сыновьями – Симом, Хамом и Яфетом – с женой и женами сыновей,","14":"а с ними все звери и скот, вид за видом, и вся живность, снующая по земле, вид за видом, и все птицы – пернатые и крылатые – вид за видом.","15":"Все они пришли к нему в ковчег, по паре от всех, в ком есть дыхание жизни,","16":"от каждого вида самец и самка, – как повелел Ною Бог. И Господь затворил за Ноем дверь ковчега.","17":"Сорок дней длился потоп. Когда вода стала прибывать, она приподняла ковчег, и ковчег поплыл.","18":"Вода все прибывала и затопляла землю. Ковчег плавал,","19":"а вода поднималась все выше, пока не покрыла самые высокие горы, какие есть под небом.","20":"На пятнадцать локтей поднялась над ними вода, и горы исчезли под водой.","21":"И погибли тогда все, кто жил на земле: и птицы, и скот, и звери, и все твари, какими была полна земля, и все люди.","22":"Все, в чьих ноздрях было дыхание жизни, все обитатели суши, – все умерли.","23":"Все, что было на земле, – и люди, и скот, и всякая живность, и птицы небесные – все было сметено с лица земли. Уцелел лишь Ной и те, кто был с ним в ковчеге.","24":"Наводнение продолжалось сто пятьдесят дней."},"8":{"1":"И вспомнил Бог про Ноя и про тех животных, диких и домашних, что были с Ноем в ковчеге. Бог послал на землю ветер, и воды отступили.","2":"Затворились жерла пучины, закрылись небесные створы, и прекратился дождь.","3":"И вода стала медленно уходить с земли. На сто пятидесятый день вода начала спадать:","4":"в семнадцатый день седьмого месяца ковчег остановился на Араратских горах.","5":"Вода медленно отступала; настал десятый месяц года. В первый день десятого месяца показались вершины гор.","6":"Прошло сорок дней. Отворив сделанное им окошко,","7":"Ной выпустил наружу ворона, и, пока земля не просохла, тот кружил, то улетая, то возвращаясь.","8":"Следом Ной выпустил голубя, чтобы узнать, кончилось ли наводнение,","9":"но голубь не нашел, на что сесть, и вернулся, так как вся земля была еще под водой. Ной протянул руку и взял голубя в ковчег.","10":"Спустя семь дней он выпустил голубя снова.","11":"Тот вернулся вечером – с листом маслины в клюве, и Ной понял, что наводнение кончилось.","12":"Он подождал еще семь дней, снова выпустил голубя, и тот больше не возвращался.","13":"На шестьсот первый год жизни Ноя, в первый день первого месяца, вода спала. Ной отворил ковчег и увидел, что вода сошла с земли.","14":"В двадцать седьмой день второго месяца, когда земля просохла,","15":"Бог сказал Ною:","16":"«Выйди из ковчега, вместе с женой, сыновьями и женами сыновей.","17":"И всех животных выведи – и птиц, и скот, и живность, снующую по земле: пусть земля будет ими полна, пусть они будут плодовиты и многочисленны».","18":"И Ной вышел из ковчега, вместе с сыновьями, женой и женами сыновей,","19":"а следом вышли звери, мелкая живность, птицы – все обитатели земли, вид за видом.","20":"Ной воздвиг жертвенник Господу и принес жертвы всесожжения из всех видов чистых животных и птиц.","21":"Вдыхая запах жертв, Господь сказал Себе: «Впредь не буду Я насылать на землю проклятие из – за людей. Хотя их мысли с самой юности устремлены к злу, Я не стану больше истреблять все живое.","22":"Не прекратятся, доколе стоит земля: сев и жатва, холод и зной, лето и зима, день и ночь»."},"9":{"1":"Бог благословил Ноя и его сыновей: «Будьте плодовиты и многочисленны, заселяйте землю.","2":"Пусть все звери на земле, и все птицы в небе, и вся живность земная, и все рыбы в морях страшатся вас и трепещут пред вами: они отданы в вашу власть.","3":"Всех животных Я отдаю вам в пищу, как прежде отдал зелень растений.","4":"Но не ешьте мяса, в котором есть жизнь – то есть кровь.","5":"И за вашу кровь – за отнятую жизнь – Я взыщу с того, кто прольет эту кровь, будь то зверь, будь то человек, отнявший жизнь у брата своего.","6":"Если кто прольет кровь человека, кровь убийцы другой пусть прольет. Ибо человек создан как образ Божий.","7":"Будьте же плодовиты и многочисленны, заселяйте землю и господствуйте над нею!»","8":"Бог сказал Ною и его сыновьям:","9":"«Я заключаю договор с вами и вашими потомками,","10":"и со всеми живыми существами, которые вместе с вами покинули ковчег: с птицами, скотом и зверями – со всеми животными земли.","11":"Я беру вас под свое покровительство. Впредь уже воды потопа не станут губить все живое, больше потоп не будет опустошать землю».","12":"Бог сказал: «Вот знак этого договора, который Я заключаю навеки, из рода в род, с вами и со всем живым:","13":"Я повесил на облаках свой лук, радугу, в знак договора между Мною и жителями земли.","14":"Когда Я соберу облака над землей, то в облаках появится радуга.","15":"Тогда Я вспомню Свой договор с вами и со всем живым – и потопа, который губит все живое, уже не будет.","16":"В облаках будет радуга – Я увижу ее и вспомню Свой вечный договор со всеми жителями земли».","17":"Бог сказал Ною: «Это знак договора, который Я заключил со всеми, кто живет на земле».","18":"Сыновья Ноя, вышедшие из ковчега, – это Сим, Хам и Яфет (Хам – это отец Ханаана).","19":"Трое их было, и от них происходят все народы земли.","20":"Ной возделывал землю; он был первым, кто стал разводить виноград.","21":"Выпив вина, Ной опьянел и лежал обнаженный в своем шатре.","22":"Его наготу увидел Хам (отец Ханаана) – и сказал об этом братьям.","23":"Тогда Сим и Яфет накинули на плечи плащ, пятясь вошли в шатер отца и прикрыли его наготу плащом. Сами они смотрели в другую сторону, а потому не видели его наготы.","24":"Ной проснулся трезвым и, узнав, что сделал его младший сын,","25":"сказал: «Проклят Ханаан! Последним рабом быть ему у братьев!»","26":"И еще сказал: «Благословен Господь, Бог Сима! А Ханаану быть рабом у братьев.","27":"Пусть Бог расширит владения Яфета! Пусть живет Яфет в шатрах Сима! А Ханаану быть рабом у братьев».","28":"После потопа Ной жил еще триста пятьдесят лет.","29":"Прожив девятьсот пятьдесят лет, Ной умер."},"10":{"1":"Вот рассказ про потомство Ноевых сыновей – Сима, Хама и Яфета. После потопа у Сима, Хама и Яфета родились дети.","2":"Сыновья Яфета: Гомер, Магог, Мадай, Яван, Тувал, Мешех и Тирас.","3":"Сыновья Гомера: Ашкеназ, Рифат и Тогарма .","4":"Сыновья Явана: Элиша и Таршиш, а также киттеи и родане и","5":"(они заселили приморские страны). Таковы их земли, роды и племена, и у каждого из них – свой язык.","6":"Сыновья Хама: Куш, Мицраим, Пут и Ханаан.","7":"Сыновья Куша: Сева, Хавила, Савта , Раама и Савтеха. Сыновья Раамы: Сава и Дедан.","8":"У Куша был сын Нимрод – первый богатырь на свете","9":"и могучий охотник пред Господом. (Отсюда и поговорка: «Словно Нимрод, могучий охотник пред Господом».)","10":"Сперва его царство составляли Вавилон, Урук и Аккад; все они – в стране Шинар.","11":"Из этой страны он ушел в Ассирию, где построил Ниневию, Реховот – Ир и Калах,","12":"а также Ресен, что между Ниневией и Калахом (это главный город).","13":"От Мицраима произошли: лидийцы, анамеи, лехавеи, нафтухеи,","14":"патрусеи, каслухе и и кафторяне (а от них – филистимляне).","15":"От Ханаана произошли: Сидон (это его первенец) и Хетт,","16":"а также евусеи, аморе и , гиргашеи,","17":"хивве и , арке и , сине и ,","18":"арвадеи, цемареи и хаматеи. Позже ханаане й ские племена широко расселились:","19":"от Си дона их владения протянулись в сторону Герара – до Газы, а в сторону Содома, Гоморры, Адмы и Цевоима – до Лаши.","20":"Таковы потомки Хама, их языки, земли, роды и племена.","21":"Были дети и у Сима. Он – предок всех сынов Э веровых, старший брат Яфета.","22":"Сыновья Сима: Элам, Ашшур, Арпахшад, Луд и Арам.","23":"Сыновья Арама: Уц, Хул, Гетер и Маш.","24":"У Арпахшада был сын Шелах, у Шелаха – сын Эвер.","25":"У Эвера родилось двое сыновей: одного назвали Пелег, потому что как раз в его время земля была поделена, а другого – Иоктан.","26":"У Иоктана были сыновья: Алмодад, Шелеф, Хацармавет, Ярах,","27":"Хадорам, Узал, Дикла ,","28":"Овал, Авимаэл, Сава,","29":"Офир, Хавила и Иовав. Все это сыны Иоктановы,","30":"их земли простираются от Меши на восток, до Сефарских гор.","31":"Таковы потомки Сима, их языки, земли, роды и племена.","32":"Таковы семейства сыновей Ноя, их родословия и происшедшие от них народы – все народы земли произошли от них после потопа."},"11":{"1":"Во всем мире в ту пору был единый язык, одни и те же слова.","2":"Идя с востока, люди достигли равнины в стране Шинар и там поселились.","3":"«Сделаем из глины кирпичи и обожжем их в огне», – сказали они друг другу. И кирпичи заменили им камень, а асфальт служил им вместо известкового раствора.","4":"«Построим город с башней до неба, – сказали люди. – Так мы прославим наше имя, чтобы не рассеяться по свету бесследно».","5":"Господь сошел вниз посмотреть на город и башню, над которыми трудились люди.","6":"И сказал Господь: «Единый народ, у всех один язык. И ведь это только начало их дел! Что ни задумают – все им будет под силу!","7":"Так сойдем же к ним и смешаем их речь, чтобы они перестали понимать друг друга!»","8":"И рассеял их Господь по свету – так они и не достроили свой город.","9":"(Потому этот город и называется Вавилон – Господь смешал там речь всех жителей земли и рассеял оттуда людей по всему свету.)","10":"Вот рассказ про род Сима. Через два года после потопа, когда Симу было сто лет, у него родился сын Арпахшад.","11":"После рождения Арпахшада Сим жил пятьсот лет; у него были еще сыновья и дочери.","12":"Когда Арпахшаду было тридцать пять лет, у него родился сын Шелах.","13":"После рождения Шелаха Арпахшад жил четыреста три года; у него были еще сыновья и дочери.","14":"Когда Шелаху было тридцать лет, у него родился сын Эвер.","15":"После рождения Эвера Шелах жил четыреста три года; у него были еще сыновья и дочери.","16":"Когда Эверу было тридцать четыре года, у него родился сын Пелег.","17":"После рождения Пелега Эвер жил четыреста тридцать лет; у него были еще сыновья и дочери.","18":"Когда Пелегу было тридцать лет, у него родился сын Реу .","19":"После рождения Реу Пелег жил двести девять лет; у него были еще сыновья и дочери.","20":"Когда Реу было тридцать два года, у него родился сын Серут.","21":"После рождения Серуга Реу жил двести семь лет; у него были еще сыновья и дочери.","22":"Когда Серугу было тридцать лет, у него родился сын Нахор.","23":"После рождения Нахора Серуг жил двести лет; у него были еще сыновья и дочери.","24":"Когда Нахору было двадцать девять лет, у него родился сын Терах.","25":"После рождения Тераха Нахор жил сто девятнадцать лет; у него были еще сыновья и дочери.","26":"Когда Тераху было семьдесят лет, у него родились сыновья Аврам, Нахор и Харан.","27":"Вот рассказ про род Тераха. У Тераха родились сыновья Аврам, Нахор и Харан. У Харана был сын Лот,","28":"сам же Харан умер еще при жизни Тераха, своего отца, на родине, в Уре Халде й ском.","29":"Аврам и Нахор женились: женой Аврама стала Сара, а женой Нахора – Милька, дочь Харана (Харан был отцом Мильки и Иски ).","30":"Сара была бесплодна и детей у нее не было.","31":"Терах покинул Ур Халдейский и направился в ханаанскую землю, вместе со своим сыном Аврамом, внуком Лотом (сыном Харана) и невесткой Сарой, женой Аврама. Они дошли до Харрана и там поселились.","32":"Терах прожил двести пять лет. Он умер в Харране."},"12":{"1":"Господь сказал Авраму: «Оставь свою страну, родных, отчий дом – иди в землю, которую Я укажу тебе.","2":"Я произведу от тебя великий народ, благословлю тебя и возвеличу твое имя: ты станешь благословением!","3":"Кто тебя благословит – того Я благословлю! Прокляну того, кто тебя проклянет! Благословением ты станешь для всех народов земли!»","4":"И Аврам пустился в путь, как повелел ему Господь; Лот пошел вместе с Аврамом. Авраму было семьдесят пять лет, когда он покинул Харран.","5":"Он взял с собою жену Сару, племянника Лота, все нажитое добро и всех людей, какие были у них в Харране, и вместе с ними пошел в Ханаан. Они прибыли в Ханаан","6":"и пришли к дубу Морэ, что близ Шехема. В ту пору эта земля была населена ханаанеями,","7":"но Господь явился Авраму и сказал: «Я отдам эту землю твоим потомкам!» И Аврам воздвиг там жертвенник Явившемуся Господу.","8":"Затем он направился в горы, что лежат к востоку от Бет – Эля, и раскинул там свои шатры – Бет – Эль был от него на запад, а Ай на восток. Там Аврам воздвиг Господу жертвенник и призвал имя Господне.","9":"Затем он направился на юг, в Негев.","10":"В стране начался голод – такой сильный, что Авраму пришлось искать пристанища в Египте.","11":"Приближаясь к Египту, он сказал Саре: «Я знаю, какая ты красивая.","12":"Египтяне увидят тебя, поймут, что ты моя жена, и тебя оставят в живых, а меня убьют!","13":"Скажи им, что ты моя сестра, – и все будет хорошо: ты спасешь мне жизнь!»","14":"Аврам пришел в Египет, и египтяне увидели, как прекрасна Сара.","15":"Придворные тоже ее заметили, стали расхваливать фараону ее красоту, и Сару взяли к фараону во дворец.","16":"Дела Аврама шли хорошо благодаря Саре: у него появились и овцы, и коровы, и ослы, и рабы, и рабыни, и ослицы, и верблюды.","17":"Но Господь поразил фараона и его близких тяжкими бедами за то, что фараон взял себе жену Аврама.","18":"Фараон позвал Аврама и сказал ему: «Что ты наделал? Почему скрыл, что она твоя жена?","19":"Зачем назвал ее сестрой? А я из – за этого взял ее в жены! Забирай свою жену, – сказал фараон, – и уходи!»","20":"И фараон велел выслать Аврама из страны, вместе с женой и со всем его добром."},"13":{"1":"Аврам ушел из Египта обратно в Негев, с женой и со всем своим добром; вместе с ним ушел и Лот.","2":"Теперь Аврам был очень богат – и скотом, и серебром, и золотом.","3":"Из Негева он вернулся к Бет – Элю – к тому месту между Бет – Элем и Аем, где он останавливался прежде","4":"и где он воздвиг жертвенник, призвав имя Господне.","5":"У Лота, кочевавшего вместе с Аврамом, тоже был свой скот и свои шатры.","6":"Земли уже не хватало на двоих: столько было у них всякого добра, что жить вместе им стало тесно.","7":"Между пастухами Аврама и Лота начались ссоры (а в ту пору в этой земле жили еще и ханаанеи, и периззеи).","8":"И Аврам сказал Лоту: «Давай сделаем так, чтобы не было раздоров между нами, между твоими и моими пастухами: ведь мы с тобой родня!","9":"Вся земля перед тобою – давай разойдемся. Если ты налево – я направо. Если ты направо – я налево».","10":"Лот увидел, что Иорданская Долина – вся, вплоть до самого Цоара, – орошена водой, словно сад Господень, словно земля египетская (это было еще до того, как Господь уничтожил Содом и Гоморру).","11":"Лот выбрал Иорданскую Долину и направился на восток. Так их пути разошлись:","12":"Аврам поселился в Ханаане, а Лот – около городов Долины. Он кочевал рядом с Содомом.","13":"Жители Содома были скверные люди и много грешили против Господа.","14":"Когда Лот и Аврам расстались, Господь сказал Авраму: «Оглянись! Посмотри отсюда на север и на юг, на восток и на запад.","15":"Всю эту землю, которую ты видишь, Я навеки отдам тебе и твоим потомкам.","16":"Я сделаю твое потомство многочисленным, словно песок: как не счесть на земле песчинок, так не счесть и твоих потомков.","17":"Ступай же, обойди землю, которую Я отдаю тебе, пройди ее вдоль и поперек».","18":"Переходя с места на место, Аврам достиг дубравы Мамре, что близ Хеврона, остановился там и воздвиг жертвенник Господу."},"14":{"1":"B правление Амрафела, царя шинарского, Ариоха, царя элласарского, Кедорлаомера, царя эламского, и Тидала, царя гоимского,","2":"была война: они пошли походом на Беру, царя Содома, Биршу, царя Гоморры, Шинава, царя Адмы, Шемевера, царя Цевоима, и на царя Белы (что ныне называется Цоар),","3":"собравших свои войска в долине Сиддим (ныне Мертвое море).","4":"Двенадцать лет они были под игом Кедорлаомера, на тринадцатый взбунтовались,","5":"а на четырнадцатый год пришел Кедорлаомер со своими союзниками. Они разбили рефаимов в Аштерот – Карнаиме, зузеев в Хаме, эмеев в Шаве–Кирьятаиме","6":"и хорреев в их горной стране Сеир, у Эл – Парана, что на краю пустыни.","7":"Оттуда они повернули к Эн – Мишпату (что ныне называется Каде ш ) и опустошили земли амалекитян и амореев, обитающих в Хацецон – Тамаре.","8":"Царь Содома, царь Гоморры, царь Адмы, царь Цевоима и царь Белы (что ныне называется Цоар) вышли навстречу и в долине Сиддим вступили с ними в сражение –","9":"с Кедорлаомером, царем эламским, Тидалом, царем гоимским, Амрафелом, царем шинарским, и Ариохом, царем элласарским. Четверо царей бились против пяти.","10":"А в долине Сиддим было множество ям, полных асфальта. Воины царей Содома и Гоморры обратились в бегство и увязли в этих ямах. Кто уцелел, те бежали в горы.","11":"Победители забрали все богатства Содома и Гоморры, все их припасы, и ушли прочь.","12":"Увели они и Лота, Аврамова племянника, который жил в Содоме, и забрали все его добро.","13":"Один из уцелевших пришел к Авраму – еврею, который жил у дубравы Мамре – аморея (у Мамре были братья Эшкол и Анер; они и Аврам были связаны обязательством помогать друг другу).","14":"Узнав, что племянник в плену, Аврам собрал своих людей – триста восемнадцать человек, от рождения принадлежавших к его дому, – и пустился в погоню. Около Дана,","15":"ночью, он окружил врагов, разбил их и преследовал до самой Ховы, что к северу от Дамаска.","16":"Он отбил у врагов всю добычу, и Лота с его добром, и женщин, и пленных.","17":"Когда Аврам возвращался после победы над Кедорлаомером и его союзниками, царь Содома вышел навстречу Авраму в долину Шаве (что ныне называется Царской долиной).","18":"Мелхиседек, царь Салима, жрец Бога Вышнего, вынес Авраму хлеб и вино","19":"и благословил его такими словами: «Да благословит Аврама Бог Вышний, Создатель неба и земли!","20":"Благословен Бог Вышний, Что врагов твоих предал в руки твои!» Аврам дал Мелхиседеку десятую часть всей добычи.","21":"Царь Содома сказал Авраму: «Верни моих людей, а добычу оставь себе».","22":"Аврам ответил: «Я клянусь, воздев руку к Господу, Богу Вышнему, Создателю неба и земли,","23":"что не возьму из твоего добра ничего – ни нитки, ни ремешка от сандалий. Не говори потом: „Это я сделал Аврама богатым\".","24":"Мне не нужно ничего, кроме того, что пошло моим людям на пропитание. И пусть получат свою долю те, кто ходил со мной в поход, – Анер, Эшкол и Мамре»."},"15":{"1":"Спустя некоторое время после этих событий Авраму было видение и услышал он слова Господа: «Не бойся, Аврам. Я – твой Щит. Велика будет твоя награда».","2":"Аврам сказал: «Владыка мой, Господи! Зачем мне Твои дары, если у меня нет детей? Мой дом унаследует сын Ме ш ека, Даммесек Элиэзер.","3":"Ты не дал мне детей, все отойдет моему слуге!»","4":"И было Авраму слово Господа: «Нет, не он будет твоим наследником: твой наследник будет зачат тобою!»","5":"Господь вывел Аврама из шатра и сказал ему: «Посмотри на небо, сосчитай звезды: можешь пересчитать их? Таким, – сказал Господь, – будет и твое потомство!»","6":"Аврам поверил Господу – и в этом Господь увидел его праведность.","7":"Господь сказал Авраму: «Я Господь, который привел тебя сюда из Ура Халдейского, чтобы отдать эту землю тебе во владение». –","8":"«Господь, Владыка мой! – сказал Аврам. – Где знак, что эта земля будет моей?»","9":"И Господь сказал: «Приведи мне сюда трехлетнюю корову, трехлетнюю козу, трехлетнего барана, принеси горлицу и голубя».","10":"Аврам привел животных и разрубил их пополам, а половины положил одну против другой. Птиц он разрубать не стал.","11":"Слетелись стервятники, но Аврам отогнал их.","12":"Садилось солнце. Забытье нашло на Аврама, великий и темный ужас объял его.","13":"И Господь сказал: «Знай, что твои потомки будут четыреста лет жить в чужой стране, в рабстве и угнетении.","14":"Но народ, поработивший их, Я призову на суд – и тогда твои потомки уйдут оттуда, уйдут богатыми людьми.","15":"А ты с миром отойдешь к предкам, сойдешь в могилу в глубокой старости.","16":"Лишь четвертое поколение твоих потомков возвратится сюда, ибо грехи амореев еще не достигли своей меры».","17":"Солнце зашло, и наступила тьма. Тогда явились и прошли меж рассеченными животными жаровня дымящаяся и факел пылающий.","18":"В тот день Господь заключил с Аврамом договор, взял его под свое покровительство: «Я отдаю твоему потомству всю эту землю, от Египетского потока до великой реки Евфрат, –","19":"всю землю кенеев, кениззеев, кадмонеев,","20":"хеттов, периззеев, рефаимов,","21":"амореев, ханаанеев, гиргашеев и евусеев»."},"16":{"1":"Сара, жена Аврама, была бездетна. У нее была рабыня, египтянка по имени Агарь,","2":"и Сара сказала Авраму: «Господь не дает мне детей. Живи с моей рабыней – быть может, хоть она родит мне сына». Аврам послушался Сары,","3":"и она отдала ему в наложницы свою рабыню, египтянку Агарь. В ту пору минуло уже десять лет, как Аврам поселился в Ханаане.","4":"Аврам стал жить с Агарью, та забеременела – и стала смотреть на госпожу свысока.","5":"«Ты в ответе за мое унижение, – сказала Сара Авраму. – Я отдала свою рабыню тебе в наложницы, а она, забеременев, смотрит на меня свысока. Пусть Господь нас с тобой рассудит». –","6":"«Твоя рабыня в твоей власти, – ответил Аврам. – Поступай, как тебе угодно». И Сара стала так притеснять Агарь, что Агарь убежала от нее.","7":"В пустыне, у источника, на дороге, ведущей в Шур, нашел ее ангел Господень","8":"и спросил: «Агарь, Сарина рабыня, откуда и куда ты идешь?» Та ответила: «Я бегу от Сары, моей госпожи».","9":"Ангел Господень сказал: «Вернись к госпоже и покорись ей.","10":"Я сделаю твоих потомков столь многочисленными, – сказал ангел Господень, – что их и сосчитать нельзя будет.","11":"Ты беременна, – сказал ангел Господень. – У тебя будет сын. Назови его Измаил, ибо в беде твоей Господь услышал тебя.","12":"Сын твой будет – что дикий осел, он на всех – все на него. Будет жить он в раздоре с братьями».","13":"Господу, который с нею говорил, Агарь дала имя: «Ты – Эл – Рои». Это означало: «Я воочию видела Видящего меня!»","14":"(Потому – то колодец и называется Беэр – Лахай – Рои . Он находится между Кадешем и Бе р едом.)","15":"Агарь родила Авраму сына, и Аврам дал ему – своему сыну от Агари – имя Измаил.","16":"В ту пору Авраму было уже восемьдесят шесть лет."},"17":{"1":"Когда Авраму было девяносто девять лет, Господь явился ему и сказал: «Я Бог Всесильный. Живи пред лицом Моим и будь непорочен.","2":"Я заключу с тобою договор о покровительстве и дарую тебе множество потомков».","3":"Аврам пал ниц, и Бог сказал:","4":"«Я беру тебя под Свое покровительство. Ты станешь прародителем многих народов.","5":"И имя тебе будет не Аврам, но Авраам, ибо Я сделаю тебя прародителем многих народов.","6":"Многочисленным сделаю Я твой род: целые народы произойдут от тебя и царями будут твои потомки!","7":"У Меня будет договор с тобой и с твоими потомками – договор навеки, из рода в род: Я буду твоим Богом и Богом твоих потомков.","8":"Я отдам тебе и твоим потомкам эту землю, в которой ты сейчас живешь, как чужак, – всю землю ханаанскую Я отдам твоим потомкам в вечное владение и буду их Богом».","9":"Бог сказал Аврааму: «Но и ты должен соблюдать договор со Мною, а после тебя твои потомки, из рода в род.","10":"Вот условие Моего договора с вами и вашими потомками: все мужчины у вас должны быть обрезаны. Соблюдайте этот договор.","11":"Обрезайте себе крайнюю плоть в знак договора со Мною.","12":"Каждый новорожденный мальчик у вас должен быть обрезан на восьмой день – пусть так будет из рода в род. И тот, кто родился в твоем доме, и тот, кто не от семени твоего, а куплен у иноплеменников, –","13":"непременно должны быть обрезаны и тот и другой: и родившийся в доме, и купленный. Так договор со Мною, договор навеки, будет запечатлен на вашей плоти.","14":"А необрезанный – тот, чья крайняя плоть не обрезана, – будет истреблен и отторгнут от народа своего, за то что нарушил договор со Мною».","15":"И еще Бог сказал Аврааму: «Отныне жена твоя будет зваться не Сара, а Сарра.","16":"Я благословлю ее и дам тебе сына от нее. Я благословлю ее – и целые народы произойдут от нее. И потомки ее будут царями».","17":"Авраам пал ниц, но про себя подумал, усмехнувшись: «Рождаются ли дети у столетнего старца? Сарре ли рожать, в девяносто лет?»","18":"И он сказал Богу: «Пусть хоть жизнь Измаила будет угодна Тебе!»","19":"Бог сказал: «Сарра, твоя жена, родит сына, и ты дашь ему имя Исаак. С ним и с его потомками Я заключу договор о покровительстве – договор навеки.","20":"Я внял и твоей просьбе об Измаиле: Я благословлю его, сделаю его род плодовитым и дарую ему множество потомков. Двенадцать вождей произойдут от Измаила: он станет прародителем великого народа.","21":"Но договор о покровительстве Я заключу с Исааком, которого Сарра родит тебе через год, в это же время».","22":"Так сказал Бог Аврааму – и отошел от него.","23":"В тот же самый день Авраам обрезал крайнюю плоть и своему сыну Измаилу, и всем мужчинам, принадлежавшим к его дому от рождения, и всем купленным за деньги рабам – всем мужчинам в доме. Он выполнил все, что повелел ему Бог.","24":"Девяносто девять лет было Аврааму, когда он был обрезан,","25":"а Измаилу, его сыну, – тринадцать лет.","26":"В один и тот же день были обрезаны и Авраам, и его сын Измаил,","27":"и все мужчины в доме Авраама – и те, кто принадлежал к его дому от рождения, и купленные у иноплеменников рабы."},"18":{"1":"В полуденный зной, у дубравы Мамре, когда Авраам сидел у входа в шатер, явился ему Господь.","2":"Поднял Авраам глаза – и увидел, что перед ним стоят трое путников. Он бросился к ним, поклонился до земли и сказал: «Владыка мой, окажи милость, не проходи мимо меня, раба твоего.","4":"Вам принесут воды вымыть ноги. Вы отдохнете под деревом,","5":"а я подам хлеба, чтобы вы подкрепились на дорогу – раз идете мимо меня, вашего раба». – «Хорошо, – ответили они ему, – так и сделай».","6":"Авраам вбежал в шатер и сказал Сарре: «Скорее возьми три меры муки, самой лучшей, замеси тесто и напеки хлеба».","7":"Потом он побежал к стаду, выбрал хорошего, упитанного теленка и отдал рабу, чтобы тот поскорее его приготовил.","8":"Авраам сам подал гостям сметану, молоко, телятину – и ждал, стоя под деревом, пока они поедят.","9":"«Где твоя жена Сарра?» – спросили они у Авраама. Он ответил: «Здесь, в шатре». –","10":"«Я вернусь к тебе через год, – сказал гость, – и у Сарры тогда будет сын». А Сарра слушала – она была у него за спиной, у входа в шатер.","11":"Оба они, и Авраам и Сарра, были уже глубокими стариками, и прекратилось у Сарры то, что обычно бывает у женщин.","12":"Рассмеялась она про себя и подумала: «Отцвела я – и тут пришла пора утех? Да и господин мой стар…»","13":"Но Господь сказал Аврааму: «Что это Сарра смеется: „Мне ли, старухе, рожать ребенка?\"","14":"Разве есть что – нибудь невозможное для Господа? Я вернусь к тебе в назначенный срок, через девять месяцев, и у Сарры будет сын». –","15":"«Я не смеялась», – солгала Сарра, испугавшись. «Нет, – сказал Он ей, – ты смеялась».","16":"Гости встали, чтобы продолжить свой путь, и посмотрели вниз, на долину, в сторону Содома. Авраам пошел проводить их,","17":"и Господь сказал: «Не стану Я таить от Авраама Своих замыслов.","18":"Ведь от Авраама произойдет великий и сильный народ, и Авраам будет благословением для всех племен земли.","19":"Для того Я и избрал Авраама – чтобы он заповедал и детям, и всем своим потомкам верно следовать по пути Господнему: поступать справедливо и по правде. И тогда Я, Господь, исполню все, что Я обещал ему».","20":"Господь сказал: «Вопиют злодеяния Содома и Гоморры, тяжек их грех.","21":"Спущусь и посмотрю, все ли там виновны. Быть может, не все? Проверю».","22":"Путники повернулись и пошли к Содому, но Господь остался стоять перед Авраамом.","23":"И, приблизившись к Нему, Авраам сказал: «Неужели со злодеями Ты уничтожишь и праведных?","24":"Вдруг найдется в этом городе пятьдесят праведников – так неужели Ты уничтожишь его, не пощадишь ради этих пятидесяти?","25":"Быть не может! Не сделаешь Ты такого! Не погубишь Ты праведников вместе со злодеями, не постигнет одна участь и злодея и праведника! Быть такого не может! Судия всей земли – разве может судить неправедно?»","26":"И Господь ответил: «Если Я найду в Содоме пятьдесят праведников, то ради них пощажу этот город».","27":"Тогда Авраам продолжил: «Я прах и пыль, но все же осмелюсь сказать Владыке моему:","28":"если пяти праведников недостанет до пятидесяти – неужели из – за пяти недостающих Ты уничтожишь целый город?» И Господь ответил: «Нет, не уничтожу его, если найду в нем сорок пять праведников».","29":"Авраам продолжал: «А вдруг там найдется только сорок?» И Господь ответил: «Даже если сорок, не буду этого делать».","30":"Авраам сказал: «Пусть не гневается Владыка мой на то, что я скажу. А вдруг там только тридцать праведников?» И Господь ответил: «Пощажу город, если найду в нем тридцать праведников».","31":"Авраам сказал: «Я осмелюсь спросить у Владыки моего: а если их там только двадцать?» И Господь ответил: «Пощажу ради двадцати».","32":"Авраам сказал: «Пусть не гневается Владыка мой – это последний вопрос: вдруг их там всего десять?» И Господь ответил: «Пощажу ради десяти».","33":"Сказав это, Господь ушел, а Авраам вернулся домой."},"19":{"1":"Двое ангелов пришли в Содом. Уже смеркалось. Лот сидел у городских ворот. Увидев путников, он поднялся им навстречу и сказал, поклонившись до земли: «Пожалуйте, господа мои, в дом ко мне, вашему рабу. Переночуете у меня, вымоете ноги, а наутро пойдете дальше». – «Нет, – отвечали они. – Мы лучше заночуем на улице».","3":"Но Лот так настаивал, что они согласились. Он привел их в свой дом, приготовил ужин, напек лепешек и накормил их.","4":"Не успели они лечь спать, как жители города – все мужчины Содома, от мала до велика, – со всех сторон окружили дом Лота.","5":"«Где те, кто пришли к тебе ночевать? – кричали они. – Давай их нам сюда, мы их будем насиловать!»","6":"Лот вышел на порог, закрыл дверь за собой","7":"и сказал: «Братья, не надо, не делайте этого!","8":"У меня две дочери, еще девушки, – я отдам их вам, и делайте с ними, что хотите, но не троньте тех, кто пришел под мой кров!»","9":"Но они ответили: «Прочь! Пришел, чужак, поселился у нас, а теперь распоряжаться будешь? Мы сейчас с тобой еще и не то сделаем!» Они стали напирать на Лота и уже собирались вышибить дверь,","10":"но гости Лота втащили его обратно в дом, а дверь заперли.","11":"Всех столпившихся у порога, от мала до велика, они поразили слепотой – так что те, как ни искали, не могли уже найти входа в дом.","12":"И гости сказали Лоту: «Кто еще у тебя есть в этом городе? Зять, сыновья, дочери, еще кто – нибудь? Всех уводи отсюда:","13":"мы уничтожим этот город! Злодеяния его жителей вопиют к Господу, и Господь нас послал уничтожить его!»","14":"Лот пошел и сказал женихам своих дочерей: «Скорее уходите из этого города! Господь его сейчас уничтожит!» Но те решили, что Лот шутит.","15":"Уже светало. Ангелы стали торопить Лота: «Скорее, уводи прочь жену и обеих дочерей! Не то сам погибнешь вместе с грешным городом!»","16":"А Лот все медлил. Тогда, взяв за руки Лота, его жену и обеих дочерей, ангелы сами вывели их прочь из города, ибо Господу было жаль Лота.","17":"«Спасайся! – сказал ангел Лоту. – Назад не оглядывайся! И не задерживайся в Долине – беги в горы, не то погибнешь!» –","18":"«Нет, Владыка мой! – ответил Лот. –","19":"Ты так добр ко мне, рабу твоему! Велика твоя милость ко мне: ты спас мне жизнь! Но ведь до гор мне не добежать – беда настигнет меня, и я погибну.","20":"А вон тот городок – близко, туда можно добежать, он маленький. Туда я и побегу, он маленький, там я уцелею!» –","21":"«Хорошо, – сказал ангел, – я и это сделаю ради тебя: я сохраню городок, о котором ты говоришь.","22":"Но беги туда скорее: я не могу начать, пока ты не пришел туда». (Потому этот город и называется Цоар.)","23":"Солнце взошло над землей. Лот пришел в Цоар.","24":"И обрушил Господь на Содом и Гоморру, словно дождь, серу горящую – с небес, от Господа –","25":"и уничтожил оба города, и всю Долину, и всех жителей, и все, что росло на земле.","26":"Оглянулась назад Лотова жена – и превратилась в соляной столб.","27":"Рано утром Авраам пришел туда, где накануне стоял перед Господом,","28":"поглядел на Содом и Гоморру, на Долину – и увидел: земля, как гончарная печь, дымом окутана.","29":"Уничтожая города Долины, Бог вспомнил про Авраама. Бог увел Лота от гибели, разрушая города, где жил Лот.","30":"Из Цоара Лот ушел в горы, вместе с обеими дочерьми: ему было страшно оставаться в Цоаре. Они поселились в пещере.","31":"Старшая дочь сказала младшей: «Отец стареет. На земле больше нет мужчины, который жил бы с нами, как заведено.","32":"Напоим отца вином и переспим с ним. Пусть от собственного отца, но будут у нас дети!»","33":"И на ночь они напоили отца вином. Старшая дочь пришла к нему, спала с ним, а он и не сознавал, что происходит, – ни как легла она с ним, ни как ушла.","34":"На другой день она сказала сестре: «Прошлой ночью я спала с отцом. Напоим его вином и в эту ночь, ты придешь и ляжешь с ним. Пусть от собственного отца, но будут у нас дети!»","35":"И вновь они на ночь напоили отца вином. Младшая дочь пришла и спала с ним, а он и не сознавал, что происходит, – ни как легла она с ним, ни как ушла.","36":"Так обе дочери Лота зачали детей от своего же отца.","37":"Старшая родила сына и назвала его Моав. Он – прародитель теперешних моавитян.","38":"Младшая родила сына и назвала его Бен – Амми . Он – прародитель теперешних аммонитя н."},"20":{"1":"Уйдя из этих мест на юг, в Негев, Авраам стал жить между Кадешем и Шуром, а затем нашел себе пристанище в Гераре.","2":"Он называл Сарру своей сестрой, поэтому Авимелех, царь Герара, послал за Саррой и взял ее себе.","3":"Но ночью, во сне, Бог явился Авимелеху и сказал: «Ты умрешь за то, что взял себе эту женщину. Она замужем».","4":"А Авимелех еще и не прикасался к ней. «Владыка мой! – взмолился он. – Неужели Ты уничтожишь неповинный народ?","5":"Ведь этот человек сам сказал мне, что она его сестра! И она говорила то же самое! Совесть моя чиста, и руки неповинны!» –","6":"«Да, – отвечал ему Бог во сне, – Я знаю, что совесть твоя чиста. Потому и не дал тебе овладеть этой женщиной – удержал тебя от греха предо Мною.","7":"Но теперь верни ее мужу. Он пророк, и он помолится, чтобы ты остался жив. Знай: если ты не вернешь ее мужу, то погибнешь и сам, и весь род твой!»","8":"Наутро Авимелех собрал своих приближенных, пересказал им эти слова – и все они сильно испугались.","9":"Авимелех позвал к себе Авраама и стал его упрекать: «Что ты делаешь с нами? Чем я тебя обидел, что ты ввел в такой страшный грех и меня, и все мое царство? Так не поступают!","10":"Зачем ты это сделал?» – сказал Авимелех Аврааму.","11":"Авраам ответил: «Я подумал, что в этих местах не боятся Бога и могут убить меня из – за жены.","12":"К тому же она и вправду сестра мне – дочь моего отца, только от другой матери. Она стала моей женой,","13":"но когда Бог велел мне покинуть отчий дом и отправиться в странствие, я сказал ей: „Прошу тебя, куда бы мы ни пришли, говори про меня, что я твой брат\"».","14":"Авимелех подарил Аврааму овец, коров, рабов, рабынь, вернул ему Сарру","15":"и сказал: «Вся моя земля перед тобою: где хочешь, там и живи».","16":"А Сарре он сказал: «Я даю твоему брату тысячу шекелей серебра. Это покроет твою обиду в глазах близких, и твоя честь будет восстановлена».","17":"Авраам помолился Богу, и Бог исцелил Авимелеха, его жену и служанок, и те вновь стали рожать детей","18":"(а до этого из – за Сарры, Авраамовой жены, Господь сделал бесплодными всех женщин в доме Авимелеха)."},"21":{"1":"А Господь, как обещал, вспомнил про Сарру: выполнил Господь обещание Свое.","2":"Сарра забеременела и в срок, назначенный Богом, родила престарелому Аврааму сына.","3":"Авраам дал новорожденному, своему сыну от Сарры, имя Исаак,","4":"а на восьмой день, как повелел Бог, обрезал ему крайнюю плоть.","5":"Сто лет было Аврааму, когда родился Исаак.","6":"А Сарра сказала: «Смешное сотворил со мной Бог: кто ни услышит обо мне – будет смеяться».","7":"И добавила: «Кто бы мог сказать Аврааму, что его Сарра будет грудью кормить ребенка? Но вот, на старости лет, я родила ему сына!»","8":"Ребенок подрос. В день, когда он был отнят от груди, Авраам устроил большой пир.","9":"Увидев, как сын Авраама от Агари – египтянки играет с Исааком,","10":"Сарра сказала Аврааму: «Прогони эту рабыню вместе с ее сыном! Не будет ее сын твоим наследником наравне с моим Исааком!»","11":"Больно было Аврааму слышать такие слова о своем сыне,","12":"но Бог ему сказал: «Не печалься ни о мальчике, ни о рабыне. Сделай, как говорит тебе Сарра, ибо твой род продолжится через Исаака.","13":"Но и от сына рабыни Я произведу целый народ. Ведь он тоже твое дитя».","14":"Наутро Авраам дал Агари хлеб и бурдюк с водой – положил их ей на плечи – и велел уходить, вместе с ребенком. Агарь ушла и заблудилась в Беэршевской пустыне.","15":"Кончилась вода в бурдюке. Она оставила ребенка под кустом,","16":"а сама отошла, чтобы не видеть, как он умирает, села поодаль, на расстоянии выстрела из лука, и разрыдалась.","17":"Но Бог услышал, как плачет дитя, и ангел Божий с небес окликнул Агарь: «Что с тобою, Агарь? Не бойся! Бог услышал, как плачет твое оставленное дитя.","18":"Вставай, иди к ребенку, возьми его на руки! Я произведу от него великий народ».","19":"Бог открыл ей глаза – Агарь увидела колодец. Она подошла, наполнила бурдюк и напоила ребенка.","20":"С тех пор Бог не оставлял мальчика. Тот вырос, поселился в пустыне и сделался стрелком из лука.","21":"Он жил в пустыне Паран, а жену для него мать привела из Египта.","22":"В ту пору Авимелех, сопровождаемый Пихолом, начальником его войска, пришел и сказал Аврааму: «Во всем, что бы ты ни делал, Бог тебе помогает.","23":"Так поклянись же мне Богом, что не предашь ни меня, ни детей, ни внуков моих: как я был добр с тобою, так и ты будешь добр и со мною, и со страной, приютившей тебя!» –","24":"«Я дам такую клятву», – сказал Авраам,","25":"но пожаловался, что люди Авимелеха отняли у него колодец.","26":"«Я не знаю, кто это сделал, – ответил Авимелех. – Ты мне ничего не говорил. Я первый раз об этом слышу».","27":"Авраам подарил Авимелеху овец и коров и заключил с ним союз.","28":"Семь овец он поставил особняком,","29":"и Авимелех спросил: «А эти семь овец – зачем ты их поставил особняком?» –","30":"«Прими их от меня, – ответил Авраам, – в знак того, что это мой колодец: я его выкопал».","31":"(С тех пор как они обменялись там клятвами, это место и называется Беэр – Ше в а.)","32":"Заключив в Беэр – Шеве союз с Авраамом, Авимелех и его военачальник Пихол вернулись в филистимскую землю.","33":"Авраам посадил в Беэр – Шеве тамариск и призвал имя Господа, Бога Вечного.","34":"Потом Авраам еще долго жил в филистимской земле."},"22":{"1":"Спустя некоторое время после этих событий Бог подверг Авраама испытанию. «Авраам!» – сказал ему Бог. «Да!» – отозвался Авраам.","2":"И Бог сказал: «Возьми своего сына – единственного, любимого – Исаака, и иди с ним в землю Мориа. Там, на горе, которую Я укажу тебе, ты принесешь его в жертву всесожжения».","3":"Наутро Авраам оседлал осла, взял с собой двух слуг, взял Исаака, нарубил для всесожжения дров и отправился в путь – к тому месту, о котором говорил ему Бог.","4":"На третий день пути посмотрел Авраам – и увидел вдали это место.","5":"«Побудьте здесь, постерегите осла, – сказал он слугам. – А мы с мальчиком пойдем, поклонимся Богу и вернемся к вам».","6":"Он взял дрова для всесожжения и положил их на плечи Исааку. Потом взял огниво, взял нож и пошел дальше – вдвоем с Исааком.","7":"Исаак окликнул Авраама: «Отец!» – «Да, сынок?» – отозвался Авраам. Тот спросил: «У нас есть и огниво, и дрова, но где ягненок для всесожжения?» –","8":"«Сынок, – сказал ему Авраам, – Бог видит, где ягненок для всесожжения!» И они шли дальше, вдвоем.","9":"Дойдя до места, о котором говорил ему Бог, Авраам устроил жертвенник и разложил на нем дрова. Он связал Исаака, положил его поверх дров на жертвенник,","10":"достал нож и занес над сыном.","11":"И тогда воззвал к нему с неба ангел Господень: «Авраам, Авраам!» – «Да!» – отозвался тот.","12":"«Не поднимай на него руки, – сказал ангел, – ничего ему не делай! Теперь Я знаю, что ты боишься Бога – ты не пожалел отдать Мне своего единственного сына!»","13":"И Авраам увидел барана, запутавшегося рогами в зарослях. Он подошел, взял барана и принес его в жертву всесожжения вместо сына.","14":"Место, где все это было, Авраам назвал Яхве–Ирэ. (Отсюда и поговорка: «На горе Господней будет видно».)","15":"И вновь ангел Господень воззвал к Аврааму с неба:","16":"«Самим Собою клянусь, – говорит Господь: за то, что ты это сделал – не пожалел отдать единственного сына –","17":"Я тебя благословлю! Я дарую тебе потомков, числом – как звезды на небе, как песок на морском берегу. И падут пред твоими детьми вражеские врата!","18":"Благословеньем будут дети твои для всех народов земли – за то, что ты был послушен Мне».","19":"Авраам вернулся туда, где оставил слуг, возвратился вместе с ними в Беэр – Шеву – и жил в Беэр – Шеве.","20":"Спустя некоторое время после этих событий Аврааму сказали, что Милька, жена его брата Нахора, родила сыновей:","21":"У ц а (это первенец), Буза, Кемуэла (это отец Арама),","22":"Кеседа, Хазо, Пилдаша, Идлафа и Бетуэла.","23":"У Бетуэла родилась дочь Ревекка. Это восемь сыновей, которых Милька родила Авраамову брату Нахору.","24":"Кроме того, наложница Нахора по имени Реума родила ему Теваха, Гахама, Тахаша и Мааху ."},"23":{"1":"Сарра прожила сто двадцать семь лет.","2":"Умерла она в Кирьят – Арбе (что ныне называется Хевроном), в ханаанской земле. Авраам пришел и оплакивал Сарру, рыдая над нею,","3":"а потом, отойдя от усопшей, обратился к хеттам:","4":"«Я чужак, которому вы дали приют. Выделите мне на вашей земле место, где я мог бы похоронить усопшую». –","5":"«Сделай милость, господин наш! – отвечали хетты. – Ты человек почтенный, любимый Богом. Похорони свою жену в лучшей из наших усыпальниц: любой из нас предоставит тебе для этого свою родовую усыпальницу».","7":"Поклонился Авраам хеттам, жителям этой земли,","8":"и сказал: «Если вы разрешаете мне похоронить усопшую, то сделайте милость: попросите Эфрона, сына Цохарова,","9":"продать мне пещеру Махпела, что на его поле, с краю. Я куплю ее в вашем присутствии, за полную цену серебром, чтобы она стала местом для погребения».","10":"В присутствии всех хеттов, собравшихся у городских ворот, Эфрон, сидевший среди них, ответил Аврааму:","11":"«Нет, господин мой! Сделай милость: прими это поле в дар от меня, вместе с пещерой. Мои соплеменники свидетели: я дарю тебе это поле, чтобы ты похоронил там усопшую!»","12":"Поклонившись жителям этой земли,","13":"Авраам сказал Эфрону, в присутствии всех собравшихся: «Прошу тебя, сделай милость: прими от меня серебро за поле, на котором я похороню усопшую!»","14":"Эфрон ответил:","15":"«Хорошо, господин мой! Сделай милость! Четыреста шекелей серебра стоит этот участок – разве это много для нас с тобою, чтобы ты похоронил там усопшую?»","16":"Авраам согласился с ценой Эфрона и отвесил ему столько серебра, сколько тот назначил при свидетелях – хеттах: четыреста шекелей серебра, по весу, принятому среди купцов.","17":"Так поле Эфрона, что при Махпеле, рядом с Мамре, перешло в собственность Авраама, вместе с пещерой и всеми деревьями на этом поле. А свидетелями тому были все хетты, собравшиеся у городских ворот.","19":"И Авраам похоронил свою жену Сарру в пещере, что на поле Махпела, рядом с Мамре (что ныне называется Хевроном), в ханаанской земле.","20":"А поле и пещера перешли от хеттов к Аврааму, став местом для погребения."},"24":{"1":"Авраам был уже глубоким старцем, и благословение Господне во всем ему сопутствовало.","2":"И сказал Авраам своему старшему рабу – тому, кто управлял его домом и хозяйством: «Коснись моего бедра и поклянись Господом, Богом небес и Богом земли, что не женишь моего сына на местной, на ханаанеянке,","4":"а пойдешь в мою страну, к моим родным, и оттуда приведешь жену для Исаака».","5":"Раб спросил: «А что если девушка не захочет идти со мной сюда, в эту землю? Я должен буду вернуть твоего сына в страну, откуда ты пришел?» –","6":"«Ни за что! – ответил ему Авраам. – Не возвращай моего сына туда!","7":"Господь, Бог небес, который увел меня из отчего дома на чужбину, и говорил со мной, и клялся, что отдаст эту землю моим потомкам, – Он Сам пошлет Своего ангела перед тобою, чтобы ты привел моему сыну жену.","8":"Если девушка не захочет идти с тобой, ты будешь свободен от клятвы, но не возвращай моего сына туда!»","9":"Раб коснулся бедра своего господина и произнес клятву.","10":"Потом взял десять верблюдов, принадлежавших его господину, взял с собою все его сокровища и тронулся в путь, в Арам – Нахараим – в город, где жил Нахор.","11":"Был вечер, когда он остановил своих верблюдов перед городом, у колодца, – час, когда девушки выходят из города за водой.","12":"И Авраамов раб сказал: «О Господь, Бог господина моего Авраама! Ниспошли мне сегодня удачу, не оставь моего господина!","13":"Вот, я стою у колодца, куда девушки из города ходят за водой.","14":"Я скажу одной из них: „Позволь мне напиться из твоего кувшина\". И если она ответит: „Пей. И твоих верблюдов я тоже напою\", – значит, ее Ты и избрал в жены для раба Твоего Исаака. Пусть будет это знаком, что Ты не оставил моего господина!»","15":"Не успел он вымолвить это, как с кувшином на плече подошла Ревекка, дочь Бетуэла, сына Мильки и Авраамова брата Нахора.","16":"Она была очень красива, еще девушка – мужчина еще не познал ее. Она спустилась к колодцу и наполнила кувшин. Когда она пошла обратно,","17":"Авраамов раб подбежал к ней и попросил: «Дай мне попить воды из твоего кувшина!» –","18":"«Пей, господин мой», – ответила она, тут же сняла кувшин с плеча, напоила Авраамова раба,","19":"а потом сказала: «Сейчас я принесу воды твоим верблюдам, пусть напьются вдоволь».","20":"Она быстро вылила воду в поилку для скота, снова побежала к колодцу – и так носила воду, пока не напоила всех верблюдов.","21":"Раб молча наблюдал за ней, желая удостовериться, что Господь благословил его путь.","22":"А когда верблюды напились, он дал ей золотую серьгу для носа, весом в пол – шекеля, два золотых браслета, весом в десять шекелей,","23":"и спросил: «Скажи, чья ты дочь? И найдется ли в доме твоего отца место, где переночевать?»","24":"Она ответила: «Я дочь Бетуэла, сына Мильки и Нахора».","25":"И добавила: «У нас много соломы и корма для скота. И место для ночлега найдется».","26":"И сказал Авраамов раб, склонившись и простершись ниц перед Господом: «Благословен Господь, Бог господина моего Авраама, не оставивший моего господина! Господь привел меня прямо в дом к родным моего господина!»","28":"Ревекка побежала домой, к матери, и рассказала о приезде гостя.","29":"Когда Лаван, брат Ревекки, увидел у сестры серьгу и браслеты и узнал, о чем с ней говорил приезжий, он поспешил к колодцу, подошел к Авраамову рабу – тот, вместе со своими верблюдами, все еще стоял у колодца –","31":"и сказал: «Добро пожаловать, благословенный Господом! Зачем тебе здесь стоять, когда я уже убрал дом и приготовил место для твоих верблюдов?»","32":"Авраамов раб зашел в дом. Верблюдов развьючили, принесли для них соломы и корма, а гостю и его спутникам дали воды вымыть ноги.","33":"Подали еду, но Авраамов раб сказал: «Я не стану есть, пока не расскажу, зачем меня сюда послали». – «Говори», – ответили ему.","34":"И он начал рассказывать: «Я раб Авраама.","35":"Господь щедро благословил моего господина и ниспослал ему богатство: овец и коров, серебро и золото, рабов и рабынь, верблюдов и ослов.","36":"Сарра, жена моего господина, родила ему сына, уже под старость, и все, чем мой господин владеет, он передал сыну.","37":"Господин взял с меня клятву, что я не женю его сына на местной девушке, на ханаанеянке,","38":"а пойду в его отчизну, к его родственникам, и оттуда приведу жену для его сына.","39":"Я спросил господина: „А что если девушка не пойдет со мной?\"","40":"Он ответил мне так: „Господь, пред лицом которого шла вся моя жизнь, – Он Сам пошлет с тобой Своего ангела и благословит твой путь, чтобы ты привел моему сыну жену из моего рода, из моей семьи.","41":"И если ты пришел к моим родственникам – значит, ты выполнил данную мне клятву. Даже если они не отдадут тебе девушку, ты все равно свою клятву выполнил\".","42":"И сегодня, подойдя к колодцу, я сказал: „О Господь, Бог господина моего Авраама, да будет Тебе угодно благословить мой путь!","43":"Я стою сейчас у колодца и когда сюда придет девушка за водой, я скажу ей:,Дай мне попить воды из твоего кувшина .","44":"Если она ответит:,Пей. И твоим верблюдам я тоже принесу воды , – значит, ее – то Господь и избрал в жены для сына моего господина\".","45":"Не успел я подумать это, как подходит Ревекка с кувшином на плече, спускается к колодцу и набирает воду. Я попросил у нее воды.","46":"Она тут же подала мне кувшин и сказала: „Пей. И верблюдов твоих я тоже напою\". И я напился, а потом она принесла воды верблюдам.","47":"Я спросил: „Чья ты дочь?\" – и она ответила: „Дочь Бетуэла, сына Нахора и Мильки\". Тогда я дал ей серьгу для носа и браслеты,","48":"а сам склонился и простерся ниц перед Господом. И благословил я Господа, Бога господина моего Авраама, за то что Он привел меня сюда прямым путем – взять в жены для сына моего господина девушку из рода моего господина.","49":"Теперь слово за вами: желаете ли вы исполнить просьбу моего господина? Дайте ответ, чтобы я знал, что мне делать».","50":"Лаван и Бетуэл отвечали: «От Господа это дело, не нам говорить здесь „да\" или „нет\".","51":"Вот Ревекка – бери ее с собой. Пусть свершится воля Господа и сын твоего господина возьмет ее в жены».","52":"Услышав это, Авраамов раб вновь простерся ниц перед Господом.","53":"Затем он достал для Ревекки наряды, серебряные и золотые украшения, а также дорогие подарки для ее брата и матери.","54":"После этого он и его спутники поели и легли спать, а наутро Авраамов раб сказал: «Позвольте мне вернуться к моему господину».","55":"Брат и мать Ревекки отвечали: «Пусть она поживет у нас еще хоть дней десять!» –","56":"«Не задерживайте меня, – сказал Авраамов раб. – Раз уж Господь благословил мой путь, то позвольте мне вернуться к господину!» –","57":"«Позовем ее, – предложили те, – и пусть сама решит».","58":"Они позвали Ревекку и спросили: «Пойдешь с этим человеком?» Она сказала: «Пойду».","59":"Тогда они простились с Ревеккой и ее кормилицей, с Авраамовым рабом и его спутниками,","60":"и благословили Ревекку такими словами: «Пусть твоих потомков, сестра, тысячи будут, десятки тысяч! Пусть падут пред твоими детьми вражеские врата!»","61":"Ревекка и ее служанки сели на верблюдов и поехали вслед за Авраамовым рабом. Он ехал домой и вез Ревекку.","62":"А Исаак только что вернулся из Беэр – Лахай – Рои (он жил тогда в Негеве).","63":"Вечером он вышел в поле, поглядел – и увидел приближающийся караван верблюдов.","64":"И Ревекка увидела Исаака. Она спрыгнула с верблюда","65":"и спросила у Авраамова раба: «Что за человек идет нам навстречу?» – «Это мой господин», – ответил раб. Тогда Ревекка взяла покрывало и закуталась в него.","66":"После того как раб рассказал Исааку о своем путешествии,","67":"Исаак ввел Ревекку в шатер Сарры, своей матери, и Ревекка стала его женой. Он полюбил ее. Так Исаак нашел утешение после смерти матери."},"25":{"1":"Авраам женился вновь, и новая жена, по имени Кетура ,","2":"родила ему сыновей Зимрана, Иокшана, Медана, Мидья на, Ишбака и Шуаха.","3":"У Иокшана родились Сава и Дедан. Потомки Дедана – ашшуреи, летушеи и леуммеи.","4":"Сыновья Мидьяна: Эфа , Эфер, Енох, Авида и Элдаа. Все они – потомки Кетуры.","5":"Все, что у него было, Авраам оставил Исааку.","6":"А сыновей от наложниц, щедро одарив, Авраам еще при жизни своей отослал на восток – в восточные земли, прочь от Исаака.","7":"Авраам прожил сто семьдесят пять лет.","8":"Он умер глубоким старцем, насытившись жизнью, – скончался и отошел к предкам.","9":"Сыновья, Исаак и Измаил, похоронили его в пещере Махпела, на поле Эфрона – хетта, Цохарова сына, неподалеку от Мамре.","10":"Авраам купил это поле у хеттов; там погребены и Авраам и Сарра.","11":"После смерти Авраама Господь благословил его сына Исаака. Исаак жил возле Беэр – Лахай – Рои.","12":"Вот рассказ про род Измаила, который был сыном Авраама от египтянки Агари, Сарриной рабыни.","13":"Имена сыновей Измаила, по старшинству: Невайот (первенец Измаила), Кедар, Адбеэл, Мивсам,","14":"Мишма, Дума, Масса ,","15":"Хадад, Тема, Иетур, Нафиш и Кедма.","16":"Это сыны Измаила, двенадцать вождей двенадцати племен, – их имена, селения и стоянки.","17":"Сто тридцать семь лет прожил Измаил и умер – скончался и отошел к предкам.","18":"Его потомки расселились от Хавилы до Шура, что находится у египетской границы – как идти в Ашшур. В разладе с братьями жили они.","19":"Вот рассказ про род Исаака, Авраамова сына. У Авраама родился сын Исаак.","20":"Сорок лет было Исааку, когда он взял в жены Ревекку, дочь Бетуэла – арамея из Паддан – Арама; она была сестрой Лавана – арамея.","21":"Исаак молился Господу о своей жене (она была бесплодна), и Господь внял его мольбе: Ревекка забеременела.","22":"Но сыновья у нее в животе начали драться друг с другом. «Так, – промолвила Ревекка, – что же это меня ждет?» И пошла вопросить Господа.","23":"Господь ей сказал: «Два народа в твоей утробе, два племени выйдут из чрева твоего. Один одолеет другого, и старший младшему станет рабом».","24":"Подошел срок – и родились два близнеца.","25":"Первый вышел на свет рыжий и весь волосатый, как звериная шкура; его назвали Исавом.","26":"Следом, уцепившись ручкой за пятку Исава, появился другой; его назвали Иаковом. Шестьдесят лет было Исааку, когда они родились.","27":"Мальчики выросли. Исав стал ловким охотником, человеком полей, а Иаков – тихим домоседом.","28":"Их отец Исаак любил есть дичь, а потому оказывал предпочтение Исаву, но мать, Ревекка, больше любила Иакова.","29":"Однажды, когда Иаков варил похлебку, Исав, обессилевший, вернулся с охоты.","30":"«Дай мне поесть! Вот этого, вот, красного! – сказал он Иакову. – Я совсем без сил!» (Потому – то его и прозвали Эдом.)","31":"«В обмен на первородство», – ответил ему Иаков.","32":"«Я сейчас умру, – сказал Исав. – На что мне первородство?» –","33":"«Так поклянись!» – ответил Иаков. Исав поклялся, что отдает Иакову свое первородство,","34":"а взамен получил хлеб и чечевичную похлебку. Поел он, попил, встал, пошел – а до первородства ему и дела не было."},"26":{"1":"В стране вновь случился голод (как прежде, во времена Авраама), и Исаак ушел в Герар, к филистимскому царю Авимелеху.","2":"Господь явился Исааку и сказал: «Не ходи в Египет, а живи в той стране, которую Я укажу тебе. Юна приютит тебя, а Я буду с тобой и благословлю тебя. Я исполню клятву, которую дал отцу твоему Аврааму: отдам все эти земли тебе и твоим потомкам.","4":"Я сделаю твоих потомков многочисленными, как звезды на небе, и отдам им все эти земли. Твое потомство будет благословением для всех народов земли –","5":"за то что Авраам слушался Меня и соблюдал все Мои веления: заповеди, законы и правила, данные Мною».","6":"Исаак поселился в Гераре.","7":"Когда местные жители спросили его про Ревекку, он ответил: «Это моя сестра». А сказать «жена» побоялся: как бы они его не убили из – за Ревекки, которая была очень хороша собой.","8":"Шло время. Как – то раз Авимелех, филистимский царь, увидел из окна, как Исаак забавляется с Ревеккой.","9":"Он позвал Исаака и сказал ему: «Так она твоя жена?! Зачем же ты говорил, что она тебе сестра?» Исаак ответил: «Я боялся, как бы меня не убили из – за нее». –","10":"«Что ты с нами делаешь? – сказал Авимелех. – Кто – нибудь из нас переспал бы с твоей женой – какой грех был бы на нас!»","11":"И Авимелех объявил своему народу: «Всякий, кто тронет этого человека или его жену, будет предан смерти».","12":"Поселившись в той стране, Исаак стал сеять хлеб. Господь благословил его: в тот год урожай у него был стократным.","13":"Исаак делался все богаче и богаче. Он стал настоящим богачом:","14":"теперь у него были стада овец и коров и многочисленная челядь. Филистимляне стали завидовать ему.","15":"Они засыпали и забили землей все колодцы, которые еще во времена Авраама были вырыты Авраамовыми рабами,","16":"а сам Авимелех сказал Исааку: «Уходи. Ты стал для нас слишком могущественным».","17":"Исаак ушел в Герарскую долину","18":"и принялся заново откапывать те колодцы, которые были вырыты еще при Аврааме, а после смерти Авраама засыпаны филистимлянами. Этим колодцам он возвращал те имена, которые им некогда дал Авраам.","19":"Как – то раз его рабы откопали в долине источник,","20":"но герарские пастухи стали спорить с пастухами Исаака, говоря им: «Это наша вода!» Поскольку из – за колодца вышла ссора, то его так и назвали: Э сек.","21":"Выкопали другой колодец; из – за него тоже возник спор, и его назвали Ситна .","22":"Тогда Исаак ушел еще дальше, вырыл еще один колодец, и тут уже не было споров. Исаак дал этому колодцу имя Реховот, что означало: «Господь наконец даровал нам простор, чтобы стало нас много на этой земле».","23":"Потом Исаак вернулся в Беэр – Шеву,","24":"и там, в первую же ночь, ему явился Господь. «Я Бог Авраама, твоего отца, – сказал Он. – Не бойся: Я с тобою. Я благословлю тебя и сделаю твое потомство многочисленным – Я сделаю это ради раба Моего Авраама».","25":"Воздвигнув на этом месте жертвенник и призвав имя Господне, Исаак раскинул там свои шатры, а его рабы стали копать колодец.","26":"Как раз в это время к Исааку из Герара пришел Авимелех со своим советником Ахузатом и военачальником Пихолом.","27":"«Зачем вы ко мне пришли? – спросил Исаак. – Ведь вы меня невзлюбили и прогнали прочь!» –","28":"«Мы видим, что с тобою Господь, – ответили они, – а потому хотим, чтобы нас связала клятва. Заключим договор!","29":"Поклянись, что не причинишь нам зла: ведь и мы тебе ничего худого не делали, а только добро, дали тебе уйти от нас с миром, и теперь с тобой благословение Господне!»","30":"Исаак устроил для них пир, они ели и пили.","31":"Наутро они обменялись клятвами. Исаак простился с гостями, и те с миром пошли обратно.","32":"И в тот же самый день рабы, рывшие колодец, оповестили Исаака, что они нашли воду.","33":"Исаак дал этому колодцу имя Шива. (Отсюда и сегодняшнее название города – Беэр – Шева.)","34":"Когда Исаву было сорок лет, он взял себе в жены Иехудит, дочь Беэри–хетта, и Басемат, дочь Элонахетта.","35":"Исааку и Ревекке было тяжело с ними обеими."},"27":{"1":"Однажды Исаак, уже старый и слепой, позвал к себе старшего сына. «Сынок!» – сказал он Исаву. «Да, отец!» – отозвался тот.","2":"Исаак промолвил: «Я уже стар и не знаю, сколько мне осталось жить.","3":"Возьми свое оружие – лук, стрелы – и ступай в поле за дичью.","4":"Принесешь, приготовишь мою любимую еду, а я поем и благословлю тебя перед смертью».","5":"Но Ревекка подслушала их разговор. Когда Исав отправился за дичью,","6":"она сказала Иакову: «Я слышала, как твой отец велел Исаву:","7":"„Принеси дичи и приготовь мою любимую еду. Я поем, – сказал отец, – и благословлю тебя пред лицом Господа, перед смертью\".","8":"Так вот, сынок, слушай, что тебе надо сделать.","9":"Ступай к стаду и выбери двух козлят. Я приготовлю их повкуснее, как любит твой отец,","10":"а ты отнесешь ему, чтобы он поел и дал тебе свое предсмертное благословение». –","11":"«Мой брат Исав весь волосатый, – ответил Иаков, – а у меня кожа гладкая.","12":"Вдруг отец меня ощупает? Если он поймет, что я его обманываю, то не благословение меня ждет, а проклятие».","13":"Но мать сказала: «Пусть на мне будет это проклятие, сынок. Ты только слушай меня. Ступай и принеси».","14":"Иаков принес козлят, и Ревекка приготовила их повкуснее, как любил Исаак.","15":"Затем она взяла лучшие одежды Исава, своего старшего сына, какие были в доме, и надела их на младшего, на Иакова.","16":"Руки и шею Иакова она обернула шкурами козлят,","17":"потом дала Иакову мясо и хлеб.","18":"Тот вошел к отцу и сказал: «Отец!» – «Да, сынок! – отозвался Исаак. – Ты который?» –","19":"«Я Исав, твой первенец, – ответил Иаков. – Я все сделал, как ты сказал мне. Приподнимись, сядь и поешь дичи, а потом дай мне свое благословение». –","20":"«Сынок, – спросил Исаак, – как же ты смог так быстро поймать дичь?» Тот ответил: «Господь, твой Бог, послал мне удачу». –","21":"«Подойди, сынок, – сказал Исаак. – Дай я тебя ощупаю: точно ли ты Исав?»","22":"Иаков подошел к отцу, тот ощупал его и промолвил: «Голос – Иакова, а руки – это руки Исава».","23":"Из – за того, что руки Иакова были покрыты волосами, как у Исава, Исаак не узнал его и дал ему свое благословение.","24":"«Так ты мой сын Исав?» – спросил он у Иакова. Тот подтвердил: «Да, отец».","25":"И сказал Исаак: «Дай поесть твоей дичи, сынок, и я благословлю тебя». Иаков подал отцу еду и вино. Кончив есть и пить,","26":"Исаак сказал: «Подойди, сынок, поцелуй меня».","27":"Иаков подошел, поцеловал отца, и, почуяв запах его одежд, Исаак благословил его такими словами: «Запах сына моего – это запах полей, Господом благословенных.","28":"Пусть же Бог тебя одарит росой с неба, плодами земли, изобилием хлеба и вина.","29":"Пусть народы тебе служат, племена пред тобой пусть склонятся. Будешь ты господином над братьями: сыновья твоей матери склонятся пред тобой. Проклинающий тебя проклят, благословен, кто благословит тебя!»","30":"Как только благословил Исаак Иакова, как только вышел Иаков от Исаака, с охоты вернулся Исав.","31":"Он тоже приготовил еду повкуснее, принес отцу и сказал: «Отец! Привстань, поешь дичи, которую я принес, и дай мне свое благословение!» –","32":"«Ты кто?» – спросил Исаак. Тот ответил: «Я твой сын, твой первенец, Исав».","33":"И сказал Исаак, задрожав от испуга: «А кто же тогда раздобыл дичи и накормил меня, еще до твоего прихода? Ведь я отдал ему свое благословение, с ним оно теперь и останется!»","34":"Громко и горестно закричал Исав, когда услышал эти слова, а потом стал просить отца: «Так благослови же и меня, отец!» –","35":"«Это твой брат приходил ко мне, – промолвил Исаак. – Он обманом отобрал предназначенное тебе благословение».","36":"И сказал Исав: «Не зря его зовут Иаков – он уже два раза меня обошел! Сперва отобрал мое право быть первенцем, а теперь – предназначенное мне благословение! Неужели, – спросил Исав отца, – для меня не осталось никакого благословения?»","37":"Исаак ответил: «Я сделал его твоим господином, всех родичей сделал ему рабами, отдал ему и хлеб и вино. Что же я могу сделать для тебя, сынок?» –","38":"«Неужели, – спросил Исав Исаака, – у тебя, отец мой, было лишь одно благословение? Благослови и меня, отец!» Исав зарыдал,","39":"а Исаак сказал ему: «Далеки будут твои селенья от тучной земли и от росы небесной.","40":"Ты будешь жить тем, что добудет твой меч, и будешь брату служить. Но срок придет – ты взбунтуешься и сбросишь с шеи ярмо».","41":"Исав затаил на Иакова злобу за то, что тот получил благословение отца. «Наступят дни траура по отцу, – подумал Исав, – убью моего брата Иакова!»","42":"Но Ревекке донесли о том, что замышляет ее старший сын. Она позвала к себе Иакова, младшего, и сказала ему: «Твой брат Исав собирается убить тебя.","43":"Слушай, сынок, что я тебе скажу: беги к моему брату Лавану, в Харран.","44":"Ты поживешь там, пока не стихнет ярость твоего брата,","45":"пока не пройдет его гнев против тебя и он не забудет, как ты поступил с ним, – а тогда я пошлю за тобою и заберу тебя оттуда. Иначе придет день, когда я потеряю двоих сразу!»","46":"Ревекка сказала Исааку: «Мне жизнь не мила от этих хеття н ок. Если еще и Иаков женится на местной, на хеттянке, вроде этих, мне и жить не стоит!»"},"28":{"1":"Исаак позвал Иакова, и, благословив его, дал такое наставление: «Ханаанеянок в жены не бери.","2":"Ступай в Паддан – Арам, к Бетуэлу, отцу твоей матери, и возьми себе жену из дочерей Лавана, ее брата.","3":"Да благословит тебя Бог Всесильный! Да сделает Он твой род плодовитым и многочисленным, чтобы множество народов произошло от тебя!","4":"Да передаст Он тебе и твоим потомкам благословение, данное Аврааму, – и ты овладеешь землей, где живешь как пришелец, землей, которую Бог даровал Аврааму!»","5":"Исаак простился с сыном, и тот пошел в Паддан – Арам, к Лавану, сыну Бетуэла – арамея. Лаван был брат Ревекки, матери Иакова и Исава.","6":"Исав узнал, что Исаак благословил Иакова и послал его за женой в Паддан – Арам, узнал, что вместе с благословением отец дал Иакову наказ не брать в жены ханаанеянок","7":"и что Иаков, повинуясь отцу с матерью, уже пошел в Паддан – Арам.","8":"Тогда Исав понял, что невестки – ханаанеянки не по душе его отцу,","9":"пошел к измаильтя нам и взял себе еще одну жену – Махалат, дочь Авраамова сына Измаила, сестру Невайота.","10":"Покинув Беэр – Шеву, Иаков направился в Харран.","11":"Дойдя до некоего места, он остановился, застигнутый ночью, и лег спать, подложив под голову камень.","12":"Во сне он увидел лестницу, соединявшую небо и землю; ангелы Божьи поднимались и спускались по ней.","13":"Господь стоял на вершине и говорил Иакову: «Я Господь, Бог Авраама, отца твоего, и Бог Исаака. Эту землю, на которой ты лежишь, Я дарую тебе и твоим потомкам.","14":"Многочисленны, как песок, будут твои потомки, и расселятся они на запад и на восток, на север и на юг. Благословением для всех народов земли будешь ты и твои потомки.","15":"Я с тобой: куда бы ты ни шел, Я буду тебя хранить – и верну тебя обратно, в эту страну. Я тебя не оставлю: исполню все, что обещал».","16":"Проснулся Иаков и вымолвил: «Воистину, Господь пребывает на этом месте – а я – то и не знал!","17":"Как же страшно это место! – сказал он, пораженный ужасом. – Это же дом Бога, врата небес!»","18":"Наутро Иаков взял камень, который клал себе под голову, поставил его стоймя, как священный камень, и возлил на него оливковое масло.","19":"Место это он назвал Бет – Эль – а прежде город назывался Луз.","20":"И дал Иаков такой обет: «Если Бог будет со мною, оберегая меня в пути, подавая мне хлеб и одежду,","21":"и если я с миром возвращусь в отчий дом, то Господь станет Богом моим.","22":"Священный камень, который я поставил, станет Домом Божьим, и от всего, что Ты дашь мне, я буду отдавать Тебе десятую часть»."},"29":{"1":"Иаков отправился дальше. Дойдя до земли сынов Востока,","2":"он увидел в поле колодец, а рядом с ним три стада овец (здесь обычно поили скот). Отверстие колодца было закрыто большим камнем:","3":"когда собирались все стада, пастухи сдвигали этот камень, поили овец, а потом вновь закрывали колодец.","4":"«Откуда вы, братья?» – спросил Иаков у пастухов. «Из Харрана», – ответили те.","5":"Он спросил: «А вы не знаете Лавана, сына Нахора?» Они ответили: «Знаем». –","6":"«Как он поживает?» – спросил Иаков. «Хорошо, – отвечали ему. – Да вон и дочь его, Рахиль, идет сюда с овцами». –","7":"«Жара еще не спала, – сказал Иаков пастухам, – не время собирать скот. Напоите овец и гоните их на пастбище».","8":"Но те отвечали: «Мы не можем, пока не соберутся все стада. Тогда от колодца отодвинут камень, и мы напоим овец».","9":"Пока они разговаривали, подошла и Рахиль, ведя овечье стадо своего отца – она была пастушкой.","10":"Увидев ее со стадом, Иаков подошел к колодцу, сдвинул камень и напоил овец.","11":"Потом он поцеловал Рахиль и, громко зарыдав,","12":"сказал ей, что он родственник ее отца, сын Ревекки. Рахиль побежала передать это отцу.","13":"Услышав, что к ним пришел его племянник Иаков, Лаван бросился гостю навстречу, обнял его, расцеловал и повел в свой дом. Иаков поведал ему о себе,","14":"и Лаван сказал: «Точно, ты мой родственник, кость и плоть моя!» Минул месяц с тех пор, как Иаков поселился у Лавана,","15":"и Лаван сказал ему: «Неужели, раз ты мой родственник, ты будешь работать на меня даром? Скажи, какую ты хочешь плату?»","16":"А у Лавана было две дочери, старшую звали Лия, а младшую Рахиль.","17":"У Лии глаза были некрасивы, зато Рахиль была прекрасна и лицом и станом.","18":"Иаков полюбил Рахиль и сказал Лавану: «Я буду работать на тебя семь лет за Рахиль, твою младшую дочь». –","19":"«Что ж, – ответил ему Лаван, – пусть лучше выходит за тебя, чем за чужого. Оставайся».","20":"Семь лет Иаков работал на него за Рахиль, но эти семь лет были для него что несколько дней, потому что он любил ее.","21":"И вот, наконец, он сказал Лавану: «Где моя жена? Срок пришел, пора ей быть моей».","22":"Лаван созвал всех соседей и устроил пир.","23":"Когда стемнело, он привел к Иакову свою дочь Лию, и Иаков лег с ней.","24":"В служанки Лии Лаван отдал свою рабыню Зелфу.","25":"Настало утро – перед Иаковом Лия! «Что ты сделал со мной? – сказал Иаков Лавану. – Разве не за Рахиль я работал на тебя? Зачем ты обманул меня?» –","26":"«В наших краях не принято, – отвечал Лаван, – младшую дочь выдавать замуж вперед старшей.","27":"Вот кончится у этой свадебная неделя, мы и младшую тебе отдадим, а за это ты будешь работать на меня еще семь лет».","28":"Иаков подчинился. Когда свадебная неделя кончилась, Лаван отдал ему в жены свою дочь Рахиль,","29":"а в служанки ей дал свою рабыню Валлу.","30":"И лег Иаков с Рахилью. Он любил ее больше, чем Лию, и работал за нее на Лавана еще семь лет.","31":"Господь увидел, что Лия нелюбима, и сделал ее утробу плодовитой, а Рахиль оказалась бесплодной.","32":"Лия забеременела, родила сына и назвала его Рувим. «Господь увидел мою печаль, – сказала она. – Уж теперь – то муж меня полюбит».","33":"Потом опять забеременела – и снова родила сына. «Услышал Господь, что я нелюбима, – сказала она, – и даровал мне еще одного сына!» И назвала мальчика Симеон.","34":"Потом опять забеременела – и снова родила сына. «Уж теперь – то муж будет ко мне привязан, – сказала она, – ведь я родила ему троих сыновей!» И дала сыну имя Левий.","35":"Забеременела еще раз – и снова родила сына. «Теперь восхвалю Господа!» – сказала она и дала сыну имя Иуда. После этого она перестала рожать."},"30":{"1":"А Рахиль, видя, что не может родить Иакову ребенка, завидовала сестре. «Дай мне детей, – говорила она Иакову, – или я умру!»","2":"Но Иаков, рассерженный, отвечал ей: «Что я – Бог, который не дает тебе детей?» –","3":"«Вот Валла, моя рабыня, – сказала Рахиль. – Живи с ней, пусть родит ребенка мне на колени. Хотя бы через нее, но у меня будут дети!»","4":"И Рахиль отдала ему в наложницы свою рабыню Баллу. Иаков стал жить с Валлой,","5":"та забеременела и родила ему сына.","6":"«Бог рассудил нас, – сказала Рахиль. – Он услышал мою мольбу и дал мне сына». И она назвала мальчика Дан.","7":"А Валла вновь забеременела и родила Иакову еще одного сына.","8":"«Судом Божьим состязалась я с сестрой, – сказала Рахиль, – и одолела ее!» И она дала мальчику имя Неффалим.","9":"Тем временем Лия, подумав, что детей у нее больше не будет, отдала Иакову в наложницы свою рабыню Зелфу.","10":"Зелфа родила Иакову сына.","11":"«Удача!» – сказала Лия. И дала мальчику имя Гад.","12":"Зелфа родила Иакову второго сына.","13":"«Счастье! – сказала Лия. – Счастливицей назовут меня женщины!» И дала мальчику имя Асир.","14":"Как – то раз, в пору жатвы пшеницы, Рувим нашел в поле мандрагоры и принес их своей матери Лии. Рахиль попросила Лию: «Дай мне мандрагоры, которые нашел твой сын». –","15":"«Мало тебе, – сказала Лия, – что ты у меня мужа отняла? Теперь хочешь получить мандрагоры, которые нашел мой сын?» – «В эту ночь, – пообещала ей Рахиль, – муж будет спать с тобой, в обмен на эти мандрагоры».","16":"И вот, вечером, когда Иаков вернулся домой, Лия вышла навстречу ему и сказала: «Иди ко мне. Я откупила тебя у сестры за мандрагоры, которые нашел мой сын!» В ту ночь Иаков спал с Лией.","17":"И Господь внял ее мольбе: она вновь забеременела и родила Иакову пятого сына.","18":"«Это, – сказала Лия, – Бог воздает мне за то, что я делила мужа со своей рабыней». И она дала сыну имя Иссахар.","19":"Снова забеременела Лия, и родила Иакову шестого сына.","20":"«Щедро одарил меня Бог! – сказала она. – Уж теперь – то муж станет превозносить меня, ведь я родила ему шестерых сыновей!» И назвала сына Завулон.","21":"Потом Лия родила дочь и назвала ее Диной.","22":"Но и о Рахили вспомнил Бог, внял ее мольбе и сделал ее утробу плодоносной.","23":"Рахиль забеременела, родила сына и сказала: «Бог избавил меня от позора».","24":"Она дала сыну имя Иосиф и попросила: «Пусть прибавит мне Господь еще одного сына!»","25":"После рождения Иосифа Иаков сказал Лавану: «Позволь мне вернуться домой, на родину,","26":"вместе с детьми и женами, ради которых я работал на тебя. Сам ведь знаешь, сколько я на тебя работал!» –","27":"«Окажи милость, послушай! – сказал ему Лаван. – Мне открылось, что благодаря тебе со мною благословение Господне.","28":"Скажи, какую ты хочешь плату?» –","29":"«Сам знаешь, – отвечал Иаков, – как я на тебя работал, какими при мне стали твои стада.","30":"Немного было у тебя скота, когда я пришел, а теперь сколько! Вот как Господь благословил тебя с моим приходом! Но на свою – то семью мне когда работать?» –","31":"«Так скажи, какую ты хочешь плату?» – спросил Лаван. «Мне ничего от тебя не нужно, – отвечал Иаков. – Я готов и дальше пасти и стеречь твой скот – но с одним условием.","32":"Давай обойдем сегодня стада, чтобы ты забрал оттуда всех крапчатых, пятнистых и черных овец, а также пятнистых и крапчатых коз. А впредь такие животные будут моей платой.","33":"Тебе легко будет проверить мою честность: отныне, если ты придешь посмотреть, что я взял себе в качестве платы, и найдешь у меня козу без крапинок и пятен или овцу, которая не будет черной, – считай, что они у тебя украдены». –","34":"«Договорились, – сказал Лаван. – Будь по – твоему».","35":"И в тот же день Лаван отобрал всех пестрых и пятнистых козлов, всех крапчатых и пятнистых (то есть с белыми отметинами) коз, всех черных овец, отдал их своим сыновьям,","36":"и те удалились от Иакова на три дня пути. Иаков пас оставшийся скот Лавана.","37":"Он взял свежие ветки тополя, миндаля, платана и содрал с них полоски коры, обнажив белую древесину.","38":"Ободранные прутья он положил в поилки (откуда пьет скот), чтобы козы смотрели на эти прутья, когда приходят пить – а как раз в это время у них бывает случка.","39":"Так как козы во время случки смотрели на полосатые прутья, то козлята у них рождались пестрыми, крапчатыми и пятнистыми.","40":"А овец Иаков ставил особняком и поворачивал их так, чтоб они смотрели на пестрый и черный скот из Лавановых стад. Теперь у Иакова появились собственные стада, и он держал их отдельно от стад Лавана.","41":"Когда бывала случка у крепких животных, то Иаков клал прутья в поилки, у них перед глазами, чтобы они совокуплялись около этих прутьев.","42":"А когда случка бывала у хилых животных, тогда он прутьев не клал. Так хилый скот доставался Лавану, а крепкий Иакову.","43":"Иаков сделался настоящим богачом, у него появились стада овец и коз, рабыни и рабы, верблюды и ослы."},"31":{"1":"Иакову стало известно, что сыновья Лавана говорят про него так: «Иаков забрал у нашего отца все! Это за счет нашего отца он приобрел свое богатство!»","2":"Иаков уже и сам заметил, что Лаван смотрит на него не так, как прежде.","3":"И Господь сказал Иакову: «Вернись домой, к родным. Я буду с тобою».","4":"Иаков послал за Рахилью и Лией, чтобы они вышли в поле, где паслись его стада,","5":"и сказал: «Я смотрю, ваш отец относится ко мне уже не так, как прежде. Но со мною Бог моего отца.","6":"Сами знаете: я работал на вашего отца изо всех сил,","7":"а он меня обманывал и десять раз менял назначенную плату. Только Бог не давал ему причинить мне зла.","8":"Если ваш отец говорил мне: „Твоей платой будут крапчатые\", – весь скот рождался крапчатым. А когда говорил: „Твоей платой будут пестрые\", – весь скот рождался пестрым.","9":"Вот так и передал мне Бог стада вашего отца.","10":"Как – то раз в пору случки скота я увидел во сне, что все козлы, которые покрывали коз, были пестрыми, крапчатыми или пятнистыми.","11":"„Иаков!\" – воззвал ко мне ангел Божий во сне. Я ответил: „Да!\"","12":"И он сказал мне: „Посмотри, все козлы, что покрывают коз, – или пестрые, или крапчатые, или пятнистые. Я вижу все, что Лаван с тобой делает.","13":"Ведь Я – Бог Бет – Эля, где ты дал Мне обет, возлив оливковое масло на камень. Вставай, уходи из этой страны, возвращайся в родную землю\"».","14":"Рахиль и Лия отвечали Иакову: «Разве нам еще что – то принадлежит в отцовском имуществе или наследстве?","15":"Он считает нас чужими; он нас продал, а все, что получил за нас, присвоил себе.","16":"А раз так, то все добро, какое Бог отобрал у нашего отца, принадлежит нам и нашим сыновьям. Так что поступай, как велит тебе Бог».","17":"Иаков посадил детей и жен на верблюдов,","18":"собрал все нажитое добро, забрал скот, приобретенный им в Паддан – Араме, и направился в Ханаан, к своему отцу Исааку.","19":"Лаван как раз ушел на стрижку овец, и Рахиль взяла с собой домашних божков своего отца.","20":"Так Иаков обманул Лавана – арамея: ничего ему не сказав,","21":"ушел от него вместе со всем своим добром. Переправившись через Реку, Иаков направился к Галаадским горам.","22":"На третий день Лавану донесли, что Иаков ушел.","23":"Лаван собрал своих родичей и погнался за Иаковом. Через семь дней он нагнал его в Галаадских горах.","24":"Но той же ночью, во сне, Бог явился Лавану – арамею и сказал: «Смотри, ничего не делай Иакову!»","25":"Лаван был уже совсем рядом с Иаковом. Иаков разбил свой стан в горах. Лаван со своими родичами остановился в горах Галаада.","26":"И Лаван обратился к Иакову: «Что ты делаешь? Ты меня обманул! Угнал моих дочерей, будто пленниц, добытых на войне!","27":"Зачем ты ушел от меня тайком, обманул меня и ничего не сказал мне? Я бы проводил тебя с веселыми песнями, под звуки бубна и цитры,","28":"а ты даже не дал мне поцеловать дочерей и внуков на прощание! Глупо ты сделал.","29":"Я мог бы хорошенько отплатить вам за это, но сегодня ночью Бог вашего отца сказал мне: „Смотри, ничего не делай Иакову!\"","30":"Ладно, – продолжал Лаван, – ты ушел от меня, потому что соскучился по родному дому. Но зачем было красть моих богов?» –","31":"«Я боялся, – отвечал Иаков Лавану, – думал, ты заберешь назад своих дочерей.","32":"Но у кого найдутся твои боги, тому не быть в живых! Пусть наши родичи будут свидетелями: осмотри все, что есть у меня, и что твое – забирай!» (Иаков не знал, что это Рахиль украла божков.)","33":"Лаван обыскал шатры Иакова, Лии, обеих служанок, но ничего не нашел. Выйдя из шатра Лии, он пошел в шатер к Рахили.","34":"Рахиль тем временем взяла домашних божков, засунула их в верблюжье седло и уселась сверху. Отец стал обыскивать ее шатер, но ничего не мог найти,","35":"а Рахиль сказала ему: «Пусть не гневается господин мой, что я не могу встать перед ним: у меня обычное женское недомогание». Лаван все перерыл, но божков не нашел.","36":"Теперь уже Иаков разгневался и стал обвинять Лавана: «Так в чем же моя вина, в чем мое преступление, что ты за мной погнался?","37":"Ты перерыл все мои вещи – и что же своего ты там нашел? Давай показывай, пусть родичи нас рассудят.","38":"Двадцать лет я на тебя работал. Не было за это время выкидышей ни у овец, ни у коз. Я не ел баранов из твоего стада.","39":"Если, бывало, скотину задерут звери, я не приносил ее тебе, но сам возмещал убыток. Днем ли было дело, ночью ли – ты спрашивал с меня за пропажу.","40":"Днем меня мучил зной, ночью – холод, я глаз не смыкал.","41":"Двадцать лет я был у тебя. Четырнадцать лет я работал на тебя за твоих дочерей, шесть лет – за скот, а ты десять раз менял назначенную плату.","42":"Да если бы не был со мною Бог отца моего – Бог Авраама и Ужас Исаака – ты отослал бы меня ни с чем. Но Бог видит мою обиду и мои труды: этой ночью Он Сам за меня вступился!»","43":"И Лаван ответил Иакову: «Это ведь мои дочери, мои внуки, мой скот. Все, что ты здесь видишь, – мое. Разве я обижу своих дочерей? Или внуков?","44":"Давай заключим договор, и пусть у нас будет свидетель».","45":"Тогда Иаков поставил большой камень стоймя, как священный камень,","46":"и сказал своим родичам: «Собирайте камни». Они нагромоздили холм из камней и подле него устроили трапезу.","47":"Лаван назвал этот холм Иегар – Сахадута, а Иаков назвал его Гал – Эд.","48":"Лаван сказал: «Этот холм – свидетель нашего договора». Потому это место и называют Гал – Эд.","49":"А еще – Мицпа, ибо Лаван добавил: «Пусть Господь наблюдает за нами обоими, когда мы потеряем друг друга из виду.","50":"Если ты будешь обижать моих дочерей или возьмешь себе, кроме них, новых жен, помни: не человек, а Бог наш свидетель!","51":"Смотри, – сказал Лаван Иакову, – этот холм из камней и этот священный камень, которые я поставил между нами, –","52":"они свидетели нашего договора. И я не буду переходить со злым умыслом на твою сторону холма, и ты не переходи со злым умыслом на мою сторону холма и священного камня.","53":"Пусть нашими судьями будут Бог Авраама и бог Нахора». (То есть отчие боги Иакова и Лавана.) И поклялся Иаков Ужасом отца своего Исаака.","54":"Затем Иаков принес на Горе жертву и пригласил родичей на трапезу. После трапезы они остались на Горе ночевать.","55":"Наутро Лаван поцеловал внуков и дочерей, благословил их и отправился домой."},"32":{"1":"Иаков продолжил свой путь, и его встретили ангелы Божьи.","2":"Завидев их, Иаков сказал: «Это стан Божий». И назвал это место Маханаим.","3":"Иаков послал вестников к своему брату Исаву, в землю Сеир, в страну эдомскую,","4":"и велел передать ему такие слова: «Господину моему, Исаву. Так говорит раб твой, Иаков: я долго жил на чужбине, у Лавана.","5":"Теперь у меня есть быки и ослы, овцы, рабы и рабыни. Я посылаю тебе, господину моему, эту весть и надеюсь снискать твое благоволение».","6":"Вернувшись, вестники сказали Иакову: «Мы были у твоего брата Исава. Он идет навстречу тебе, и с ним четыреста человек».","7":"Страшно стало Иакову; ужас объял его. Он развел своих людей, скот, верблюдов по двум стоянкам.","8":"«Если, – думал Иаков, – Исав нападет на одну из стоянок и всех перебьет, то хотя бы те, кто на другой стоянке, спасутся бегством».","9":"И взмолился Иаков: «О, Боже отца моего Авраама, Боже отца моего Исаака – Господь, что повелел мне вернуться домой, к родным, и обещал Свое покровительство!","10":"Я не достоин щедрот и милостей, какими Ты непрестанно осыпал меня, раба Своего. Я уходил за Иордан с одним лишь посохом в руке, а ныне у меня два стана с добром.","11":"Спаси же меня от моего брата Исава! Страшно мне: он придет и убьет нас всех, вместе с женщинами и детьми!","12":"А ведь Ты обещал мне Свое покровительство, Ты обещал, что мое потомство будет несчетно, как песок морской!»","13":"Иаков переночевал там, а наутро отобрал из своих стад дары для Исава:","14":"двести коз, двадцать козлов, двести овец, двадцать баранов,","15":"тридцать дойных верблюдиц с верблюжатами, сорок коров, десять быков, двадцать ослиц и десять ослов.","16":"Он передал их рабам – так, чтобы у каждого гурта был свой погонщик, – и сказал погонщикам: «Идите вперед, на расстоянии друг от друга».","17":"«Когда встретишь моего брата Исава, – сказал Иаков первому из погонщиков, – и он тебя спросит: „Чей ты раб? Куда идешь? Чей скот гонишь?\" –","18":"отвечай: „Это скот раба твоего Иакова, посланный в дар господину моему Исаву. А сам Иаков идет следом\"».","19":"И второму погонщику, и третьему, и всем остальным Иаков велел при встрече с Исавом говорить то же самое –","20":"и непременно прибавлять: «Раб твой Иаков идет следом». Так, посланными вперед дарами, Иаков надеялся умилостивить Исава. «А потом, – думал Иаков, – я и сам покажусь ему на глаза. Быть может, тогда он встретит меня по – доброму».","21":"И, отправив дары вперед, Иаков остался в стане на ночлег.","22":"Но той же ночью Иаков встал, поднял обеих своих жен, обеих наложниц, одиннадцать сыновей и вброд перешел реку Яббок.","23":"Он перевел их всех на другой берег, переправил все, что у него было,","24":"и остался один. И вот, Некто вступил с ним в схватку – и боролся с ним до самой зари.","25":"Увидев, что не может одолеть Иакова, Он ударил его по бедру – так, что кость вышла из сустава, –","26":"и сказал Иакову: «Отпусти Меня. Уже заря». – «Не отпущу, пока не благословишь меня», – ответил Иаков.","27":"«Как твое имя?» – спросил Тот. Он ответил: «Иаков».","28":"И тогда Тот сказал: «Отныне ты будешь зваться не Иаков, а Израиль, ведь ты боролся с Богом и с людьми – и выходил победителем». –","29":"«Назови мне свое имя!» – попросил Иаков. Но Тот сказал: «Зачем тебе знать Мое имя?» И благословил Иакова.","30":"Место, где это было, Иаков назвал Пени–Э л, что означало: «Здесь я видел Бога лицом к лицу и остался жив».","31":"Взошло солнце. Иаков покинул Пенуэл. Он хромал.","32":"(Поэтому сыны Израилевы с тех пор и доныне не едят бедренной мышцы. Ведь именно по этой мышце, по бедру, Он ударил Иакова.)"},"33":{"1":"Иаков поглядел и увидел: навстречу ему идет Исав, и с ним четыреста человек. Иаков велел детям Лии, Рахили и обеих наложниц встать рядом с матерями.","2":"Он поставил их так: впереди – наложниц с их детьми, за ними Лию с ее детьми, а за ними Рахиль и Иосифа.","3":"Сам Иаков вышел вперед и, прежде чем приблизиться к брату, простерся перед ним на земле семь раз.","4":"Но Исав бросился ему навстречу, обнял, прижал к груди, поцеловал – и оба заплакали.","5":"Увидев женщин и детей, Исав спросил: «А это кто у тебя?» Иаков ответил: «Это дети, которыми Бог одарил меня, твоего раба».","6":"Наложницы со своими детьми подошли и поклонились Исаву.","7":"Потом подошла и поклонилась Лия со своими детьми, а потом Иосиф с Рахилью.","8":"«А что за гурты я встретил по дороге?» – спросил Исав. «Это чтобы снискать твое благоволение, господин мой», – ответил Иаков.","9":"«У меня всего хватает, брат, – сказал Исав. – Оставь свое добро себе».","10":"«Нет, – ответил Иаков, – окажи милость, прими мои дары! Свидеться с тобой было для меня – что Бога увидеть лицом к лицу, но ты так добр ко мне!","11":"Прими мой дар, мое благословение. Бог щедро одарил меня, у меня есть все». Иаков упрашивал Исава, и тот согласился принять дары.","12":"«Трогаемся в путь, – сказал Исав Иакову. – Я пойду с тобой».","13":"Но Иаков ответил: «Ты знаешь, господин мой, как слабы дети. А овцы и коровы у меня дойные: если их погнать, все падут за один день.","14":"Лучше ты, господин мой, ступай вперед, а я, раб твой, пойду следом – тихонько, как идет скот, как идут дети, пока не доберусь к тебе, господину моему, в Сеир». –","15":"«Давай я оставлю с тобой часть моих людей», – предложил Исав. Но Иаков ответил: «Зачем? Ты, мой господин, слишком добр ко мне».","16":"И в тот же день Исав пустился в обратный путь, в Сеир,","17":"а Иаков направился к Суккоту. Там он построил себе дом, а для скота сделал шалаши. (Потому это место и называется Суккот.)","18":"Вернувшись из Паддан – Арама, Иаков благополучно достиг города Шехема, что в Ханаане, и остановился неподалеку.","19":"Участок земли, где он разбил стан, Иаков купил у сыновей Хамора, Шехемова отца, за сто кесит.","20":"Там он воздвиг жертвенник и назвал его Эл – Элохе–Исраэл."},"34":{"1":"Дина, дочь Иакова от Лии, пошла к местным девушкам.","2":"Шехем, сын хиввея Хамора, правителя этой страны, увидел ее, схватил – и овладел ею.","3":"Полюбил он Дину, дочь Иакова, привязался к ней, говорил ей нежные слова,","4":"а Хамору, своему отцу, сказал: «Возьми эту девушку мне в жены».","5":"Иаков узнал, что его дочь Дина обесчещена. В ту пору его сыновья пасли скот в поле; Иаков не стал ничего делать до их прихода.","6":"Хамор, отец Шехема, пришел к Иакову поговорить с ним –","7":"и тут сыновья Иакова, узнав, что произошло, вернулись домой. Они были в гневе и ярости, ведь насилие над дочерью Иакова – это страшное оскорбление Израилю: так поступать нельзя!","8":"Хамор сказал: «Шехем, мой сын, пленился вашей дочерью. Отдайте ее ему в жены!","9":"Вы с нами породнитесь, будете отдавать нам в жены своих дочерей и брать наших дочерей себе в жены.","10":"Живите с нами вместе, наша страна перед вами – можете селиться в ней, свободно по ней странствовать, владеть землей».","11":"А сам Шехем обратился к отцу и братьям Дины с такими словами: «Сделайте милость, я дам вам все, что скажете!","12":"Назначьте самый большой выкуп и самые богатые дары – я дам вам все, что скажете, только отдайте эту девушку мне в жены».","13":"На это сыновья Иакова ответили Шехему и его отцу Хамору хитростью – ведь Шехем обесчестил их сестру Дину.","14":"«Мы не можем этого сделать, – сказали они. – Отдать сестру необрезанному мужчине будет для нас позором.","15":"На одном лишь условии мы согласимся: если вы станете как мы и все мужчины у вас будут обрезаны.","16":"Тогда мы будем отдавать вам в жены своих дочерей и брать ваших дочерей себе в жены, тогда мы поселимся с вами и станем с вами одним народом.","17":"А если вы не послушаетесь нас и не сделаете себе обрезание, то мы забираем нашу сестру и уходим».","18":"Хамор и Шехем согласились на эти условия.","19":"Шехем сделал себе обрезание тут же – так сильно он любил дочь Иакова. А Шехем был самым уважаемым человеком в роду своего отца.","20":"И вот, став перед городскими воротами, Хамор и Шехем сказали горожанам:","21":"«Эти люди настроены мирно. Пусть они селятся на нашей земле и свободно по ней странствуют. Места для них много. Мы будем брать их дочерей себе в жены и давать им в жены наших дочерей.","22":"Но они согласны с нами жить и стать с нами одним народом лишь на одном условии: чтобы все мужчины у нас были обрезаны, как и у них.","23":"Их стада, их имущество, их скот – все это будет нашим, если только мы примем их условия и они станут жить с нами вместе!»","24":"Горожане согласились с Хамором и Шехемом, и все мужчины города сделали себе обрезание.","25":"А на третий день, когда они еще лежали больные, Симеон и Левий, сыновья Иакова, братья Дины, взяли мечи, без помех вошли в город и перебили в нем всех мужчин до единого.","26":"Зарубили Хамора и Шехема, забрали Дину из Шехемова дома и ушли.","27":"Затем, вернувшись на место бойни, сыновья Иакова разграбили город, где была обесчещена их сестра.","28":"Они угнали овец, коров, ослов, взяли все, что нашли в городе и на поле,","29":"забрали все имущество горожан, увели их детей и жен и разграбили все, что было в домах.","30":"Иаков сказал Симеону и Левию: «Вы навлекли на меня беду! Вы сделали меня ненавистным для местных жителей – ханаанеев и периззеев. У нас людей немного, а они объединятся и убьют меня, и весь наш род погибнет!»","31":"Но Симеон и Левий ему отвечали: «Нельзя поступать с нашей сестрой как с продажной девкой!»"},"35":{"1":"Бог сказал Иакову: «Встань, иди в Бет – Эль. Поселись там и воздвигни там жертвенник Богу, который явился тебе, когда ты бежал от своего брата Исава».","2":"Иаков сказал своей семье и всем своим людям: «Уберите прочь всех чужих богов, какие у вас есть, очиститесь и перемените одежды.","3":"Мы идем в Бет – Эль. Там я воздвигну жертвенник Богу, который приходил мне на помощь в беде и был со мною в моих скитаниях».","4":"Они отдали Иакову всех чужих богов, какие у них были, вынули из ушей серьги и тоже отдали Иакову. Все это Иаков зарыл под Шехемским дубом.","5":"Они тронулись в путь. Объятые ужасом Божьим, жители окрестных городов не стали преследовать сыновей Иакова.","6":"Иаков со своими людьми вышел к городу Лузу (ныне Бет – Эль), что в земле ханаанской,","7":"и воздвиг там жертвенник. Он назвал это место «Эль – Бет – Эль», ибо там ему явился Бог – когда Иаков бежал от брата.","8":"Умерла Девора, кормилица Ревекки. Ее похоронили близ Бет – Эля, под дубом, и назвали этот дуб Аллон – Бахут.","9":"После возвращения Иакова из Паддан – Арама Бог вновь явился ему, благословил его","10":"и сказал: «Имя твое Иаков, но впредь не будут тебя звать Иаковом. Отныне твое имя – Израиль!» Так Он дал ему имя Израиль.","11":"И еще Бог сказал ему: «Я Бог Всесильный. Будь плодовит и многочислен: народ произойдет от тебя, целый сонм народов! От тебя произойдут цари!","12":"И землю, что Я дал Аврааму и Исааку, Я отдам тебе и твоим потомкам».","13":"Когда Бог ушел от Иакова,","14":"Иаков поставил священный камень на том месте, где Бог говорил с ним, и возлил на этот камень вино и оливковое масло.","15":"Он назвал это место Бет – Эль.","16":"Когда они оставили Бет – Эль и были уже неподалеку от Эфраты, у Рахили начались схватки. Роды были трудные,","17":"Рахиль мучилась. «Не бойся, – сказала повивальная бабка. – Смотри, у тебя еще один сын!»","18":"С последним вздохом умирающая Рахиль дала сыну имя Бен – Они. Но отец назвал его Вениамин.","19":"Так умерла Рахиль. Ее похоронили у дороги на Эфрату (что ныне называется Вифлеем),","20":"и Иаков поставил у ее могилы священный камень. Он стоит там и по сей день – священный камень у могилы Рахили.","21":"Израиль продолжил свой путь и разбил стан за Мигдал – Э дером.","22":"Во время стоянки Рувим переспал с Валлой, наложницей своего отца. Отец узнал об этом. У Иакова было двенадцать сыновей.","23":"Сыновья Лии: Рувим (первенец Иакова), Симеон, Левий, Иуда, Иссахар и Завулон.","24":"Сыновья Рахили: Иосиф и Вениамин.","25":"Сыновья Баллы, Рахилиной служанки: Дан и Неффалим.","26":"Сыновья Зелфы, Лииной служанки: Гад и Асир. Это сыновья Иакова, родившиеся в Паддан – Араме.","27":"Иаков пришел к своему отцу Исааку в Мамре, в Кирьят – Арбу (что ныне называется Хеврон), где некогда жил Авраам, а потом Исаак.","28":"Сто восемьдесят лет прожил Исаак.","29":"Он умер старцем, насытившись жизнью, – скончался и отошел к предкам. Его похоронили сыновья – Исав и Иаков."},"36":{"1":"Вот рассказ про род Исава – он же Эдом.","2":"Исав взял себе в жены двух ханаанеянок – Аду, дочь Элона – хетта, и Оголиваму, дочь Аны, дочери Цивеона – хиввея, –","3":"а также Басемат, дочь Измаила, сестру Невайота.","4":"От Ады у Исава родился Элифаз, от Басемат – Реуэл,","5":"а от Оголивамы – Иеуш, Ялам и Корей. Это сыновья Исава, родившиеся в Ханаане.","6":"Исав собрал своих жен, сыновей, дочерей, всех своих людей, стада, весь свой скот, все добро, которое он приобрел в Ханаане, и ушел в другую страну, прочь от своего брата Иакова.","7":"У них было так много добра, что жить вместе им стало тесно: земли, на которой они поселились, уже не хватало на двоих, с их стадами.","8":"Исав поселился у горы Сеир (Исав – это Эдом).","9":"Вот рассказ про род Исава, прародителя эдомитя н, жившего в Сеирских горах.","10":"Сыновья Исава: Элифаз, сын Исава от Ады, и Реуэл, сын Исава от Басемат.","11":"Сыновья Элифаза: Теман, Омар, Цефо, Гатам и Кеназ.","12":"Тимна, наложница Элифаза, родила ему Амале к а. Это потомки Исава от Ады.","13":"Сыновья Реуэла: Нахат, Зерах, Шамма и Мизза. Это потомки Исава от Басемат.","14":"От Оголивамы, дочери Аны, дочери Цивеона, у Исава родились Иеуш, Ялам и Корей.","15":"Вот кланы потомков Исава. Потомки Элифаза, Исавова первенца: клан Темана, клан Омара, клан Цефо, клан Кеназа,","16":"клан Корея, клан Гатама и клан Амалека. Это кланы Элифазовы, потомки Ады, они живут в эдомской земле.","17":"Потомки Реуэла, Исавова сына: клан Нахата, клан Зераха, клан Шаммы и клан Миззы. Это кланы Реуэловы, потомки Исава от Басемат, они живут в эдомской земле.","18":"Потомки Исава от Оголивамы: клан Иеуша, клан Ялама и клан Корея. Это кланы Оголивамы, Исавовой жены, дочери Аны.","19":"Таковы потомки Исава (он же Эдом) и их кланы.","20":"Сыновья Сеира – хоррея, жившие в этой стране: Лотан, Шовал, Цивеон, Ана ,","21":"Дишон, Э цер и Дишан. Это кланы хорреев, потомков Сеира, жившие в стране эдомской.","22":"Сыновья Лотана: Хори и Хемам. Сестру Лотана звали Тимна .","23":"Сыновья Шовала: Алван, Манахат, Гевал, Шефо и Онам.","24":"Сыновья Цивеона: Айя и Ана (тот самый Ана, который нашел в пустыне источник, когда пас ослов своего отца Цивеона).","25":"Дети Аны: Дишон и Оголивама, дочь Аны.","26":"Сыновья Дишона: Хемдан, Эшбан, Итран и Керан.","27":"Сыновья Эцера: Билхан, Зааван и Акан.","28":"Сыновья Дишана: Уц и Аран.","29":"Таковы кланы хорреев: клан Лотана, клан Шовала, клан Цивеона, клан Аны,","30":"клан Дишона, клан Эцера и клан Дишана. Это перечень хоррейских кланов, живших в земле Сеир.","31":"Вот цари, которые правили в Эдоме, еще до того как появились цари у израильтя н .","32":"Сперва правил в Эдоме Бела, сын Беора, его столица звалась Динхава.","33":"Когда Бела умер, его сменил Иовав, сын Зе р аха из Боцры .","34":"После смерти Иовава воцарился Хушам из страны потомков Темана.","35":"После смерти Хушама воцарился Хадад, сын Бедада (тот самый, который разбил мидьянитя н на моавских равнинах), его столица звалась Авит.","36":"После смерти Хадада воцарился Самла из Масреки .","37":"После смерти Самлы воцарился Саул из Реховота – Приречного.","38":"После смерти Саула воцарился Баал – Ханан, сын Ахбора.","39":"После смерти Баал – Ханана, сына Ахборова, воцарился Хадар, его столица звалась Пау, а его женой была Мехетавель, дочь Матред, дочери Ме – Захава.","40":"Вот Исавовы кланы, их семейства, селения и имена. Клан Тимны, клан Алвы, клан Иетета,","41":"клан Оголивамы, клан Элы, клан Пинона","42":"клан Кеназа, клан Темана, клан Мивцара,","43":"клан Магдиэла и клан Ирама. Таковы кланы Эдома и их селения в стране, которой они владеют. Прародитель эдомитян – Исав."},"37":{"1":"А Иаков поселился в Ханаане – в стране, где прежде жил его отец.","2":"Вот рассказ про род Иакова. Иосифу было семнадцать лет. Он пас овец вместе с братьями – помогал сыновьям Баллы и Зелфы – и ябедничал на них отцу.","3":"Иосиф родился у Иакова уже на склоне лет, так что Иаков любил его больше, чем прочих сыновей, даже подарил ему цветную рубаху.","4":"Когда братья увидели, что отец любит Иосифа больше, чем их, они так возненавидели Иосифа, что не могли даже разговаривать с ним по – доброму.","5":"Как – то раз Иосифу приснился сон. Он рассказал его братьям – и те возненавидели его еще сильнее.","6":"«Послушайте, – сказал он, – что мне приснилось!","7":"Будто мы вяжем снопы в поле и мой сноп стал прямо, а ваши снопы окружили его и поклонились ему!»","8":"Братья ответили: «Так ты, значит, царствовать над нами собрался? Начальником быть над нами?» И возненавидели его еще больше – и за сны его, и за рассказы.","9":"А Иосифу снова приснился сон, и он снова рассказал его братьям: «А я видел во сне, будто солнце, и луна, и одиннадцать звезд поклонились мне!»","10":"Когда он рассказал этот сон отцу и братьям, то отец отругал его: «Что за сны тебе снятся? Получается, что мы все – и я, и твоя мать, и твои братья – придем и падем тебе в ноги?»","11":"Братья разозлились на Иосифа, но отец запомнил его рассказ.","12":"Как – то раз братья Иосифа ушли пасти отцовских овец в окрестностях Шехема.","13":"Израиль сказал Иосифу: «Твои братья пасут скот под Шехемом. Давай я и тебя к ним пошлю». – «Я готов», – ответил Иосиф отцу.","14":"«Сходи, – сказал тот, – посмотри, как у них там дела, что со скотом. Вернешься и расскажешь мне». Отец простился с Иосифом, и, оставив Хевронскую долину, Иосиф пошел в Шехем.","15":"Там ему встретился какой – то человек. «Что ты здесь ищешь?» – спросил он у Иосифа, бродившего по полю.","16":"«Я ищу своих братьев, – ответил Иосиф. – Скажи мне, где они пасут скот?» –","17":"«Они отсюда ушли, – сказал ему тот, – я слышал, как они говорили, что пойдут в Дотан». Иосиф пошел за братьями – и нашел их в Дотане.","18":"Те уже издали приметили Иосифа и, пока он приближался, сговорились его убить.","19":"«Вот и наш сновидец! – сказали они друг другу. –","20":"Убьем его, бросим в яму и скажем, будто звери его загрызли. Вот и поглядим, как сбудутся его сны!»","21":"Рувим это услышал и спас Иосифа. «Не надо его убивать, – сказал Рувим. –","22":"Зачем проливать кровь? Чем убивать его своими руками, бросьте его лучше вон в ту яму посреди пустыни». (На самом деле он хотел спасти Иосифа и вернуть его отцу.)","23":"Как только Иосиф подошел к братьям, они сорвали с него цветную рубаху,","24":"схватили его и бросили в яму. Яма была пустая; воды в ней не было.","25":"Только братья сели за еду, как увидели, что со стороны Галаада показался караван измаильтя н – их верблюды везли в Египет благовонные смолы, ладан и бальзам.","26":"Иуда сказал: «Какой нам прок убивать брата? Придется скрывать пролитую кровь.","27":"Лучше продадим его измаильтянам, и наши руки будут чисты. Ведь он нам все – таки брат, родная плоть». Братья согласились.","28":"Когда мидья н ские купцы подошли ближе, то братья вытащили Иосифа из ямы и продали измаильтянам за двадцать шекелей серебра, а те повели его в Египет.","29":"Рувим вернулся, подошел к яме – Иосифа нет! И в знак скорби он разорвал свои одежды.","30":"«Мальчика нет! – сказал Рувим, вернувшись к братьям. – А я? Куда мне деваться теперь?»","31":"Братья взяли рубаху Иосифа, зарезали козла и выпачкали рубаху в крови козла.","32":"Потом принесли ее отцу и сказали: «Вот что мы нашли! Посмотри – это рубаха твоего сына?»","33":"Увидел Иаков и закричал: «Рубаха моего сына! Его звери загрызли! Растерзали, растерзали Иосифа!»","34":"И, разорвав свои одежды, с одним лишь куском грубой ткани на бедрах, Иаков оплакивал сына много дней подряд.","35":"Сыновья и дочери пришли к нему, чтобы утешить, но Иаков не желал утешиться. «Нет! – говорил он. – Буду оплакивать сына! С плачем сойду к сыну, в Шеол!» И продолжал оплакивать Иосифа.","36":"А мидьянитяне тем временем отвели Иосифа в Египет и продали Потифару – то был сановник фараона, начальник стражи."},"38":{"1":"В ту пору Иуда, оставив братьев, поселился рядом с одним адулламитом, по имени Хира .","2":"Там ему приглянулась дочь некоего Шуа, ханаанея. Иуда взял ее в жены, лег с ней,","3":"она забеременела и родила сына – Иуда дал ему имя Эр. Юна снова забеременела, родила второго сына и дала ему имя Онан.","5":"Затем родила еще одного и назвала его Шела (это было в Кезиве).","6":"В жены своему первенцу Эру Иуда взял девушку по имени Тамар,","7":"но Эр был неугоден Господу и Господь умертвил его.","8":"Иуда сказал Онану: «Живи со вдовой брата. Заменишь брата, дашь ему потомство».","9":"Но Онан знал, что дети, рожденные Тамар, не будут считаться его детьми, а потому всякий раз, когда ложился с ней, изливал семя на землю, чтобы не зачинать детей для брата.","10":"Неугодно было Господу, что он так поступал, за это Господь и его умертвил.","11":"Иуда сказал Тамар: «Пока мой сын Шела еще не подрос, иди живи вдовой у своих родителей». (А сказал он так, потому что подумал: «Как бы еще и младший не умер, вслед за старшими!») И Тамар вернулась в родительский дом.","12":"Прошло много времени. Умерла дочь Шуа, жена Иуды. Когда траур кончился, Иуда вместе со своим приятелем Хирой – адулламитом пошел в Тимну, на стрижку своих овец.","13":"Когда Тамар узнала, что ее свекор пошел на стрижку овец в Тимну,","14":"она сняла с себя вдовьи одежды, закрыла лицо покрывалом и села, закутавшись, у входа в Энаим, что лежит на пути в Тимну. (Ведь она видела, что хотя Шела подрос, ее так и не берут ему в жены.)","15":"Взглянув на Тамар, Иуда принял ее за продажную женщину, так как ее лицо было скрыто покрывалом.","16":"Он подошел к ней – она сидела на обочине дороги – и сказал: «Я с тобой лягу». Ведь он не знал, что это его невестка! А та спросила: «А что ты мне дашь, если ляжешь со мной?» –","17":"«Я пошлю тебе козленка», – ответил он. Но она сказала: «Пока не прислал, оставь залог». –","18":"«Какой залог ты хочешь?» – спросил Иуда. Она ответила: «Твою печать на шнурке и посох, который у тебя в руках». Он дал ей все, что она просила, переспал с ней, и Тамар зачала от него ребенка.","19":"Потом встала, ушла, сняла с лица покрывало и вновь надела свои вдовьи одежды.","20":"Когда Иуда послал своего приятеля – адулламита с козленком, чтобы получить обратно залог, тот, сколько ни искал, не мог ее найти","21":"и стал спрашивать у местных жителей: «Где блудница, что сидела при дороге в Энаиме?» Но ему отвечали: «Не было там никакой блудницы».","22":"Он вернулся к Иуде и сказал: «Я ее не нашел. А местные люди говорят, что там и не было никакой блудницы».","23":"Иуда ответил: «Пусть лучше остаются эти вещи при ней, не будем себя позорить. Я посылаю ей козленка, а ты не можешь ее найти!»","24":"Месяца через три Иуде сказали: «Согрешила Тамар, твоя невестка, и теперь беременна». – «Возьмите ее и сожгите на костре», – распорядился Иуда.","25":"Но когда Тамар повели на казнь, она попросила передать своему свекру: «Я беременна от того, кому принадлежат вот эти вещи. Узнаешь, – спросила она, – эту печать со шнурком и посох?»","26":"Иуда узнал. «Правда на ее стороне, – сказал он. – Все из – за того, что я не отдал ее моему сыну Шеле». Больше Иуда с нею не спал.","27":"Тамар пришло время рожать, и оказалось, что у нее близнецы.","28":"Когда начались роды и наружу высунулась ручка, то повивальная бабка повязала на нее алую ниточку и сказала: «Этот вышел первым».","29":"Но ребенок втянул ручку обратно и на свет появился его брат. «Как это ты прорвался?» – спросила повивальная бабка; младенца назвали Парецем.","30":"За ним появился на свет и другой, с алой ниточкой на руке. Его назвали Зерахом."},"39":{"1":"Иосифа привели в Египет, и там египтянин по имени Потифар – сановник фараона, начальник стражи – купил его у измаильтян.","2":"Господь был с Иосифом, и удача сопутствовала ему. Иосиф жил в доме хозяина,","3":"и египтянин увидел, что Господь с Иосифом – ведь во всем, что бы Иосиф ни делал, Господь ему помогал.","4":"Иосиф понравился египтянину, стал его слугой, а потом хозяин поручил Иосифу управлять домом и отдал под его начало все, чем владел.","5":"С тех пор, благодаря Иосифу, благословение Господне пребывало на всем, что принадлежало египтянину – и в доме, и в поле.","6":"Все, чем владел, передал хозяин под начало Иосифу – теперь вся забота египтянина была лишь есть да пить. Иосиф был красив и лицом, и станом.","7":"Жена господина обратила на него свои взоры и сказала: «Ложись со мной».","8":"Но Иосиф отказался, ответив ей так: «Господин отдал под мое начало все, чем владеет, а сам уже ни за чем в доме не смотрит.","9":"Я в этом доме распоряжаюсь с ним наравне. Нет для меня ничего запретного – кроме тебя: ты жена его. Как же могу я сделать такое зло, так согрешить перед Богом?»","10":"День за днем она его уговаривала, но Иосиф не соглашался лечь с нею.","11":"И вот однажды, когда Иосиф вошел в дом господина, чтобы выполнить свою работу, а в доме никого не было,","12":"она схватила его за одежду и опять сказала: «Ложись со мной». Оставив свою одежду у нее в руках, Иосиф бросился прочь и выбежал из дома.","13":"Она увидела, что Иосиф убежал, а его одежда у нее в руках,","14":"позвала слуг и сказала: «Смотрите: этого еврея привели сюда, чтоб он надругался над нами! Он явился и хотел меня изнасиловать! Я закричала.","15":"Он услышал, что я кричу и зову на помощь, выскочил прочь – даже одежду свою оставил – и убежал из дома!»","16":"Она держала одежду Иосифа при себе, пока не вернулся муж,","17":"и повторила мужу то же самое: «Явился ко мне раб – еврей – ты привел его сюда, чтоб он надругался над нами!","18":"Я стала кричать и звать на помощь. А он даже одежду свою оставил и убежал из дома!»","19":"Услышав рассказ жены – вот, мол, что твой раб хотел со мной сделать – господин Иосифа пришел в ярость.","20":"Он велел схватить Иосифа и бросить в тюрьму – туда, где содержались узники царя. Так Иосиф оказался в тюрьме.","21":"Но Господь был с ним и явил ему Свою милость: Иосиф понравился начальнику тюрьмы.","22":"Тот отдал под начало Иосифу всех узников в тюрьме. Иосиф отвечал за все,","23":"а начальник тюрьмы мог уже ни о чем не беспокоиться – ведь Господь был с Иосифом и помогал ему во всех его делах."},"40":{"1":"Спустя некоторое время после этих событий царский виночерпий и царский пекарь провинились перед своим владыкой, царем египетским.","2":"Разгневался фараон на своих приближенных – главного виночерпия и главного пекаря –","3":"и велел посадить их в темницу при доме начальника стражи, в ту самую темницу, где сидел Иосиф.","4":"Начальник стражи назначил Иосифа прислуживать им. Прошло время,","5":"и как – то ночью обоим заключенным – и царскому виночерпию, и царскому пекарю – приснились сны. Каждому приснился свой сон, со своим значением.","6":"Иосиф пришел к ним наутро и увидел, что они взволнованы.","7":"«Что вас заботит?» – спросил Иосиф. И приближенные фараона, заключенные вместе с Иосифом в доме его господина, «ответили: «Мы видели сны, а толкователей здесь нет». Иосиф сказал: «Толкования – от Бога. Поведайте мне ваши сны».","9":"И главный виночерпий рассказал: «Мне снилось, будто передо мной – виноградная лоза.","10":"На ней три побега. Они стали расти, появились цветы, показались гроздья, созрели ягоды.","11":"А в руке у меня – кубок фараона. Я сорвал гроздья, выжал сок в кубок и поднес фараону». –","12":"«Вот истолкование твоего сна, – сказал ему Иосиф. – Три побега – это три дня.","13":"Пройдет три дня, и фараон тебя вновь возвысит: вернет тебя на твое прежнее место и ты снова, как раньше, будешь подавать ему кубок.","14":"Но окажи услугу: когда счастье улыбнется тебе, то не забудь, вспомни обо мне в разговоре с фараоном, освободи меня отсюда!","15":"Ведь меня похитили из еврейской земли! Да и здесь я не сделал ничего такого, чтобы бросать меня в темницу!»","16":"Главный пекарь увидел, что толкование благоприятно, и сказал Иосифу: «А мне снилось, будто у меня на голове три корзины;","17":"в верхней – всякие лакомства, какие пекут для фараона, и птицы клюют из этой корзины». –","18":"«Вот истолкование твоего сна, – сказал ему Иосиф. – Три корзины – это три дня.","19":"Пройдет три дня – фараон и тебя возвысит: ты будешь висеть на виселице и птицы будут клевать твое тело».","20":"А через три дня у фараона был день рождения, и он устроил пиршество для своих приближенных. Двоих возвысил он в тот день на глазах у всех: главного виночерпия и главного пекаря.","21":"Главного виночерпия – на его прежнее место, чтобы вновь подавал фараону кубок.","22":"А главного пекаря – на виселицу: все, как предсказывал Иосиф.","23":"Но главный виночерпий забыл и про Иосифа, и про его просьбу."},"41":{"1":"Прошло два года, и фараону приснился сон: будто бы стоит он над Нилом,","2":"а из Нила выходят семь коров. Красивые, упитанные, они пасутся в прибрежных зарослях.","3":"Следом выходят из Нила другие семь коров, хилые и тощие, становятся с ними рядом –","4":"и вот, эти хилые и тощие коровы съедают коров красивых и упитанных! Фараон проснулся.","5":"А когда снова уснул, то увидел другой сон: семь колосьев выросли на одном стебле, хорошие, налитые.","6":"Следом из земли выросли семь колосьев пустых, сожженных суховеем –","7":"и вот, эти пустые колосья поглотили семь налитых колосьев, полных зерном! Фараон проснулся. Таков был его сон.","8":"Наутро, встревоженный, он созвал всех египетских магов и мудрецов, рассказал им свое сновидение, но никто не мог его истолковать.","9":"Тогда сказал фараону главный виночерпий: «Вспоминаю я свой былой грех!","10":"Как – то раз прогневался фараон на рабов своих – и велел заключить меня в дом начальника стражи, вместе с главным пекарем.","11":"Однажды ночью нам обоим приснились сны, каждому – свой сон, со своим значением.","12":"А при нас был слуга, еврей, раб начальника стражи. Мы рассказали ему наши сны, и он истолковал их нам – каждому сказал, что значит его сон.","13":"Как говорил он нам, так и вышло: меня вернули на прежнее место, а того, другого, повесили».","14":"Фараон послал за Иосифом. Его поспешно вывели из темницы, побрили, переодели, и он предстал перед фараоном. Фараон сказал:","15":"«Я видел сон, но никто не может истолковать его. А ты, говорят, как услышишь сон – сразу его истолковываешь».","16":"Иосиф ответил: «Не я – Бог даст истолкование на благо фараону».","17":"И фараон рассказал Иосифу: «Мне снилось, будто стою я на берегу Нила,","18":"а из Нила выходят семь коров. Упитанные, красивые, они пасутся в прибрежных зарослях.","19":"А следом за ними из Нила выходят другие семь коров, тощие, хилые, кожа да кости – я нигде в Египте не видывал таких хилых коров.","20":"И эти коровы, тощие и хилые, съедают семь упитанных коров!","21":"Те исчезли у них в животах, но не было заметно, чтобы животы наполнились: коровы остались такими же тощими, как и прежде. И я проснулся.","22":"А потом я видел другой сон: семь колосьев выросли на одном стебле, хорошие, полные зерна.","23":"А за ними следом поднялись семь колосьев тощих, пустых, сожженных суховеем –","24":"и эти тощие колосья без остатка поглотили семь хороших колосьев! Я поведал свои сны магам, но они мне ничего не объяснили».","25":"И сказал фараону Иосиф: «Это не два сна, а один. Бог открывает фараону, что Он намерен сделать.","26":"Семь хороших коров означают семь лет, и семь хороших колосьев – это тоже семь лет. Так что это один и тот же сон.","27":"А что за ними следом вышли семь коров худых и скверных – это следующие семь лет. И семь пустых колосьев, сожженных суховеем, означают то же самое – семь лет голода.","28":"Как я уже говорил фараону: Бог показывает фараону, что Он намерен сделать.","29":"Наступают семь лет изобилия по всей египетской земле,","30":"но за ними идут семь лет голода – такого, что все прежнее изобилие исчезнет без следа. Голод опустошит страну,","31":"от былого изобилия и следа не оставит – таким сильным будет этот голод.","32":"А дважды этот сон приснился потому, что это все Богом уже решено, и Он скоро исполнит Свое решение.","33":"Так пусть же фараон выберет человека мудрого и проницательного и поставит его управлять Египтом.","34":"И пусть по всей стране фараон назначит чиновников, чтобы в грядущие семь лет изобилия взимать с народа пятую часть урожая","35":"и собирать зерно в городах, в царские закрома.","36":"Тогда в стране будут запасы на семь лет голода, который наступит в Египте, – и страна переживет этот голод!»","37":"Слова Иосифа пришлись по душе фараону и его приближенным.","38":"«Другого такого человека не найти, – сказал фараон своим приближенным. – В нем дух Божий!»","39":"Потом он обратился к Иосифу: «Раз Бог открыл тебе все это, значит нет никого мудрее и проницательней тебя.","40":"Отныне ты будешь править моими владениями и народ мой будет тебя слушаться. Лишь царским саном я буду выше тебя.","41":"Смотри, – сказал фараон Иосифу, – я делаю тебя правителем всего Египта!»","42":"Он снял свой перстень с печаткой и надел его Иосифу. Он облачил Иосифа в одежды из тончайшего льна и возложил ему на шею золотую цепь.","43":"Он дал Иосифу колесницу, предназначенную для второго человека в государстве, – и перед Иосифом, когда он ехал, несся крик: «Аврех!». Так фараон сделал Иосифа правителем всего Египта.","44":"«Вот моя воля, воля фараона, – сказал он Иосифу. – Отныне без твоего ведома по всей египетской земле никто шага не посмеет ступить, рукой не шевельнет!»","45":"Фараон нарек Иосифу новое имя, Цафнат – Панеах, и отдал ему в жены Аснат, дочь Поти – Перы, гелиопольского жреца. И отправился Иосиф управлять Египтом.","46":"Тридцать лет было Иосифу в ту пору, когда он стал служить фараону, царю египетскому. Вышел Иосиф от фараона и отправился в путь, чтобы объехать египетскую землю.","47":"В течение семи плодородных лет земля давала обильные урожаи.","48":"Все зерно, которое в эти годы собирали в Египте, Иосиф распределял по городам: в каждый город – урожай с окрестных полей.","49":"Он собрал зерна, что песка морского – столько, что и считать перестал: не счесть.","50":"В это время, еще до наступления голода, Аснат, дочь гелиопольского жреца Поти – Перы, родила Иосифу двоих сыновей.","51":"Первенцу Иосиф дал имя Манассия, что означало: «Бог дал мне забыть и все мои горести, и отчий дом мой».","52":"А второго назвал Ефрем, что означало: «Сделал меня Бог плодоносным в земле страданий моих».","53":"Семь плодородных лет в Египте подошли к концу.","54":"Настали, как и предсказывал Иосиф, семь лет голода. Этот голод поразил все страны, но в Египте повсюду были запасы зерна.","55":"Когда настал голод и египтяне стали просить у фараона хлеба, фараон сказал: «Идите к Иосифу и делайте, что скажет Иосиф».","56":"Во всем мире был голод. Иосиф открыл житницы и стал продавать египтянам зерно (голод в Египте становился все сильнее).","57":"Из соседних стран тоже шли за зерном в Египет, к Иосифу, так как голод свирепствовал по всей земле."},"42":{"1":"Узнав, что в Египте есть зерно, Иаков сказал сыновьям: «Что смотрите друг на друга?»","2":"И продолжал: «Говорят, в Египте есть зерно. Отправляйтесь туда и купите зерна, чтобы нам не умереть с голода».","3":"И десять братьев Иосифа отправились в Египет за зерном.","4":"Только Вениамина, его родного брата, Иаков от себя не отпустил: как бы с ним не стряслось беды.","5":"Сыновья Израиля оказались в толпе просителей, пришедших в Египет за зерном – ведь от голода страдал весь Ханаан.","6":"А правителем страны, куда они пришли, был Иосиф – он и занимался продажей зерна. Братья подошли и простерлись перед ним ниц.","7":"Он посмотрел на них и узнал, но притворился чужим и сурово спросил их: «Откуда пришли?» – «Из Ханаана, за зерном», – ответили те.","8":"(Иосиф узнал своих братьев, но они – то его не узнали!)","9":"Вспомнил Иосиф свои сны про них и сказал: «Вы лазутчики. Пришли разведать, где наша страна уязвимее всего». –","10":"«Нет, господин! – отвечали они. – Мы, рабы твои, пришли за зерном.","11":"Мы все братья, дети одного отца, люди честные! Мы, рабы твои, никогда лазутчиками не были!» –","12":"«Нет, – сказал Иосиф, – вы пришли разведать, где наша страна уязвимее всего». –","13":"«Нас, рабов твоих, двенадцать братьев, – отвечали они. – Мы все дети одного отца, из Ханаана. Младший сейчас с отцом. А одного из нас уже нет». –","14":"«Ну вот, – сказал Иосиф, – я же говорил: вы лазутчики.","15":"Но мы вас проверим. Клянусь жизнью фараона: пока ваш младший брат не придет, вас отсюда не выпустят.","16":"Пошлите за ним кого – нибудь одного, а остальные пока будут под стражей – вот и посмотрим, правдивы ли ваши рассказы. А если нет – значит, вы лазутчики. Клянусь жизнью фараона!»","17":"И Иосиф посадил их на три дня в тюрьму.","18":"На третий день он сказал им: «Сделаете, как я скажу, – и будете жить, ибо я боюсь Бога.","19":"Если вы и вправду честные люди, пусть кто – нибудь один останется в тюрьме, а остальные отвезут зерно для своих голодающих семей","20":"и вернутся ко мне с младшим братом. Если ваши слова подтвердятся, то вы не умрете». Они подчинились.","21":"«Это нам возмездие за брата! – говорили они между собой. – Ведь мы видели его горе, но не сжалились, как он нас ни умолял. Вот теперь и к нам пришло горе!»","22":"А Рувим добавил: «Разве не говорил я вам: „Не делайте мальчику зла\"? Но вы не слушали. А теперь мы расплачиваемся за его кровь».","23":"Не знали братья, что Иосиф понимает их разговор, – ведь Иосиф говорил с ними через переводчика.","24":"А Иосиф отошел в сторону и заплакал. Потом вернулся и снова говорил с ними, а потом выбрал Симеона и велел связать его на глазах у братьев.","25":"Потом распорядился наполнить им вьюки зерном, каждому положить обратно в мешок его серебро и дать еды на дорогу. Так и было сделано.","26":"Братья нагрузили зерно на ослов и отправились домой.","27":"Ночью, на привале, один из них развязал мешок, чтобы задать корм ослу, и увидел свое серебро – вот оно, сверху!","28":"«Мое серебро снова у меня! – сказал он братьям. – Вот оно, сверху!» Сердце у них упало. Задрожав, они стали спрашивать друг у друга: «Что же это такое творит с нами Бог?»","29":"Вернувшись в Ханаан, к отцу, братья рассказали ему все, что с ними приключилось:","30":"«Человек, который правит в той земле, говорил с нами сурово и принял нас за лазутчиков.","31":"Мы сказали, что мы люди честные, а не лазутчики,","32":"что нас двенадцать братьев, все дети одного отца, что одного брата уже нет, а младший сейчас с отцом, в Ханаане.","33":"Но он ответил нам: „Я проверю, правду ли вы сказали: задержу одного из вас, а остальные пусть отвезут зерно своим голодающим семьям","34":"и возвращаются ко мне с младшим братом. Вот тогда я поверю, что вы не лазутчики, а честные люди – и брата вашего отпущу, и разрешу вам свободно странствовать по всей нашей земле\"».","35":"Они стали выкладывать вещи из мешков, и у каждого в мешке оказался кошель с серебром. Увидев это, и братья, и отец пришли в ужас.","36":"«Вы отнимаете у меня сыновей одного за другим, – сказал им Иаков. – Иосифа нет. Симеона нет. Вениамина забираете. Все беды на меня!»","37":"Рувим ответил отцу: «Двух сыновей моих можешь убить, если я не приведу Вениамина обратно. Доверь его мне – и я верну его». –","38":"«Нет, – сказал Иаков, – не пойдет с вами мой сын. Его брат мертв, Вениамин один у меня остался. Что если в пути с ним случится беда? По вашей вине я, седой старик, от скорби сойду в Шеол!»"},"43":{"1":"Но голод становился все сильнее.","2":"Когда зерно, привезенное из Египта, кончилось, отец сказал им: «Привезите еще хоть немного зерна!»","3":"Иуда ответил: «Тот человек предупреждал нас строго – настрого, чтобы мы без младшего брата ему и на глаза не показывались.","4":"Если ты его с нами отпустишь, то мы пойдем за зерном для тебя.","5":"А если не отпустишь, незачем нам и идти, раз тот человек велел нам без брата и на глаза ему не показываться». –","6":"«Ну зачем навлекли вы на меня это несчастье, – сказал Израиль, – зачем проговорились, что у вас есть еще один брат?»","7":"Они ответили: «Тот человек обо всем расспрашивал: о нас самих, о наших родных, жив ли наш отец, есть ли у нас еще братья. Он спрашивал, мы отвечали. Кто же мог знать, что он прикажет, чтобы мы привели к нему младшего брата?»","8":"И сказал Иуда своему отцу Израилю: «Отпусти его со мною, и мы пойдем. И тогда все выживут, спасутся от голодной смерти – и мы, и ты сам, и наши дети.","9":"Я головой тебе ручаюсь, что он вернется. С меня и спросишь: если не приведу его к тебе обратно, то до конца дней буду перед тобой виновен.","10":"А ведь если б мы не медлили, мы б уже два раза сходили туда и обратно!» –","11":"«Ну что ж, – сказал Израиль, – тогда сделайте вот что: наполните свои мешки всем, чем богата наша земля – бальзамом, медом, ладаном, благовонными смолами, фисташками, миндалем – и отвезите этому человеку в дар.","12":"Серебра с собой возьмите вдвое больше – чтобы вернуть то, что вам положили в мешки; они там, похоже, ошиблись.","13":"Берите Вениамина с собой и ступайте опять к этому человеку.","14":"Пусть Бог Всесильный сделает его милостивым к вам, чтобы он отпустил и того брата, и Вениамина! А что до меня – коль суждено мне терять детей, так значит суждено».","15":"Братья приготовили дары, серебра взяли вдвое больше, чем в прошлый раз, и, придя в Египет, предстали перед Иосифом – на этот раз вместе с Вениамином.","16":"Когда Иосиф увидел, что с ними Вениамин, то сказал своему управляющему: «Отведи этих людей ко мне в дом. Забей, сколько нужно, скота и приготовь еды – сегодня в полдень они будут обедать со мною».","17":"Выполняя распоряжение Иосифа, управляющий повел братьев к нему в дом.","18":"Но по дороге, испугавшись, братья стали говорить друг другу: «Нас туда ведут из – за серебра, которое тогда оказалось у нас в мешках! Они на нас нападут, набросятся на нас, захватят нас в рабство и заберут наших ослов!»","19":"И на пороге дома они обратились к управляющему:","20":"«Позволь сказать, господин наш! Мы уже приходили сюда один раз за зерном.","21":"А ночью, на привале, по дороге обратно, мы открыли наши мешки, и у каждого в мешке, сверху, оказалось его серебро – ровно столько, сколько он заплатил. Мы это серебро принесли обратно.","22":"И еще принесли серебра, чтобы купить зерно. А кто тогда подложил нам серебро в мешки, мы не знаем». –","23":"«Успокойтесь, – сказал им управляющий, – не бойтесь. Наверно, ваш Бог – Бог вашего отца – тайно положил это вам в мешки. Ваше серебро я тогда получил сполна!» Он вывел к ним Симеона,","24":"пригласил их всех в дом Иосифа, принес им воды вымыть ноги и задал ослам корма.","25":"Братья разложили свои дары, чтобы в полдень встретить Иосифа: им уже сказали, что они будут там обедать.","26":"Когда Иосиф вернулся домой, они поднесли ему дары и пали перед ним ниц,","27":"а он приветствовал их и спросил: «Как поживает ваш старец – отец, о котором вы мне рассказывали? Жив ли он?» –","28":"«Отец наш, раб твой, жив и здравствует», – ответили братья и, поклонившись, простерлись перед ним на земле.","29":"Иосиф посмотрел на Вениамина, своего родного брата. «Так это, – сказал он, – и есть ваш младший брат, о котором вы говорили мне?» И промолвил: «Да будет Бог милостив к тебе, сынок!»","30":"Сердце его сжалось от любви к брату, он едва не разрыдался, поспешно ушел в другую комнату и там заплакал.","31":"Потом умылся, вновь вышел к гостям и, взяв себя в руки, приказал подать еду.","32":"Иосифу подавали отдельно, гостям отдельно, египтянам отдельно (египтяне не едят вместе с евреями, чтобы не оскверниться).","33":"Братья расселись перед Иосифом по порядку, от старшего к младшему, и в изумлении переглядывались.","34":"А Иосиф посылал им кушанья со своего стола – причем Вениамину впятеро больше, чем остальным. И пили они, и пировали вместе с Иосифом."},"44":{"1":"Иосиф сказал своему управляющему: «Наполни их мешки зерном, сколько смогут увезти. И каждому в мешок, сверху, положи обратно его серебро.","2":"А в мешок младшего, вместе с серебром, положи еще и мою серебряную чашу». Управляющий сделал, как приказал Иосиф.","3":"Едва рассвело, гостей отпустили домой, вместе с их ослами.","4":"Братья вышли из города, но не успели еще далеко уйти, как Иосиф сказал управляющему: «Скорей, догони их! А догонишь, скажи: „Зачем вы отплатили злом за добро?","5":"Зачем украли у меня серебряную чашу? Ведь господин мой пьет из этой чаши и гадает по ней. Худое дело вы сделали!\"»","6":"Управляющий догнал их и сказал, что было велено.","7":"Братья ответили: «Зачем ты, господин наш, говоришь такое? Не могли мы, рабы твои, такого сделать.","8":"Ведь даже серебро, которое оказалось у нас в мешках, мы привезли тебе обратно – из Ханаана! Так неужели мы стали бы красть у твоего господина серебро или золото?","9":"Да если у кого из нас найдется украденное, пусть его казнят, а мы все останемся у господина нашего в рабах». –","10":"«Пусть будет, как вы сказали, – ответил управляющий, – но рабом станет лишь тот, у кого найдется украденное, а остальные с миром пойдут домой».","11":"Братья поспешно опустили свои мешки на землю и развязали их.","12":"Управляющий обыскал всех по порядку – от старшего к младшему – и чаша нашлась у Вениамина.","13":"Братья разорвали свои одежды в знак скорби, вновь навьючили ослов и вернулись в город.","14":"Иосиф был дома, когда пришли Иуда и братья. Они пали перед ним ниц,","15":"а Иосиф сказал им: «Как могли вы это сделать? Неужели не знаете, что такие люди как я искусны в гадании?» –","16":"«Что можем мы сказать господину нашему? – промолвил Иуда. – Что возразить? Чем оправдаться? Бог обличает нашу вину. Отныне мы рабы господина нашего – и тот, у кого нашлась чаша, и все остальные». –","17":"«Нет, – сказал Иосиф, – не сделаю я такого! У кого нашлась чаша, тот и станет моим рабом, а вы с миром возвращайтесь к отцу».","18":"Тогда Иуда сказал, подойдя к Иосифу: «Господин мой! Разреши мне, рабу твоему, говорить с тобой. Не гневайся, господин мой, на раба своего. Ведь ты – что фараон!","19":"Ты, господин мой, спрашивал нас, рабов своих, есть ли у нас отец и есть ли у нас еще братья.","20":"Мы отвечали тебе, господину нашему, что отец жив, но уже стар, и что есть у него еще младший сын. Это дитя его старости. Он один остался в живых из детей своей матери – его брат умер. Отец любит его.","21":"И ты велел нам, рабам своим, привести к тебе нашего младшего брата.","22":"Мы сказали тебе, господину нашему, что нельзя ему покидать отца: отец не переживет разлуки.","23":"Но ты сказал нам, рабам своим, чтобы без младшего брата мы больше и на глаза тебе не показывались.","24":"Когда мы вернулись домой, к нашему отцу, рабу твоему, мы передали ему твои слова, господин мой.","25":"А когда отец снова велел нам привезти немного зерна,","26":"мы отвечали, что без младшего брата не пойдем, что без него нам нельзя тебе и на глаза показываться.","27":"И наш отец, раб твой, сказал нам так: „Сами знаете: двух сыновей родила мне жена.","28":"Один пропал. Его растерзали звери, – подумал я. С тех пор я его не видел.","29":"Теперь вы и второго забираете. А если и с ним случится беда? По вашей вине я, седой старик, от горя сойду в Шеол!\"","30":"Так разве могу я, – спросил Иуда, – вернуться домой, к отцу, рабу твоему, без сына, к которому он так привязан?","31":"Отец увидит, что его с нами нет, – и умрет. И наш отец, раб твой, седой старик, по нашей вине от скорби сойдет в Шеол!","32":"Я, раб твой, головой поручился отцу, что брат вернется: если не приведу его домой, то до конца дней буду виновен перед отцом.","33":"Так пусть же я, раб твой, здесь и останусь вместо него! А он пусть возвращается с братьями.","34":"Не могу я вернуться домой без него и видеть горе отца!»"},"45":{"1":"Иосиф был уже не в силах сдерживаться при посторонних. «Выйдите все!» – закричал Иосиф. И никого не было рядом, когда Иосиф открыл своим братьям, кто он.","2":"Но рыдал он так громко, что египтяне услышали, и слух долетел до двора фараона.","3":"«Я Иосиф, – сказал он братьям. – Что с отцом?» А те, остолбенев, не в силах были вымолвить ни слова.","4":"«Подойдите», – сказал Иосиф. И братья подошли. «Это я, Иосиф, – сказал он им, – ваш брат, которого вы продали в Египет.","5":"Но не мучьтесь, не терзайте себя за это. Ведь Бог послал меня сюда, чтобы спасти вам жизнь.","6":"Вот уже два года, как длится голод, и еще пять лет не будет ни пахоты, ни жатвы.","7":"Бог послал меня сюда прежде вас, чтобы ваш род уцелел на земле – уцелел и стал многочисленным.","8":"Не вы – Бог отправил меня сюда и сделал так, что я стал фараону отцом – господином над всем, что ему принадлежит, и правителем всей земли египетской.","9":"Спешите к отцу, скажите ему: „Так говорит твой сын Иосиф: Бог сделал меня правителем всего Египта. Не медли, приходи ко мне.","10":"Ты поселишься вблизи от меня, в земле Гошен, вместе с сыновьями и внуками, вместе со всеми стадами и со всем своим добром.","11":"Там я устрою твою жизнь так, чтобы ни тебе, ни твоей семье, ни твоему скоту ни в чем не терпеть нужды – потому что впереди еще пять лет голода\"».","12":"«Смотрите же! – воскликнул Иосиф. – Смотри, Вениамин, брат мой! Ведь это я, я говорю с вами!","13":"Расскажите отцу, как велик я и славен в Египте. Расскажите про все, что вы видели здесь и скорее приводите сюда отца!»","14":"Он обнял Вениамина, своего брата, и зарыдал – и Вениамин рыдал, обнимая его.","15":"Потом, рыдая, Иосиф расцеловал остальных братьев – и начались разговоры.","16":"Весть о том, что к Иосифу пришли братья, долетела и до двора фараона. Фараон и его приближенные были рады,","17":"и фараон сказал Иосифу: «Вели братьям навьючить своих ослов и идти в Ханаан,","18":"чтобы привести сюда отца и свои семьи. Я дам им все самое лучшее, что есть в Египте, – пусть наслаждаются изобилием нашей страны!","19":"Вели им взять в Египте повозки для детей и женщин; и пусть они с собою привезут отца.","20":"А об оставленном имуществе им горевать не стоит: у них будет все самое лучшее, что есть в Египте!»","21":"Так и сделали сыновья Израиля. Иосиф дал им повозки, как и велел фараон, а также еды на дорогу","22":"и каждому – новую одежду. Вениамину он дал триста шекелей серебра и пять новых одежд.","23":"Отцу он послал на десяти ослах все, чем богата египетская земля, а на десяти ослицах – зерно, хлеб и прочее продовольствие на дорогу.","24":"«Идите, не бойтесь», – сказал он братьям на прощание.","25":"Они покинули Египет и вернулись в Ханаан к отцу.","26":"«Иосиф жив, – сказали они Иакову, – он теперь правит всем Египтом». Замерло у Иакова сердце: не мог он поверить.","27":"Но сыновья пересказали ему слова Иосифа, он увидел своими глазами повозки, которые Иосиф прислал, чтобы забрать его, – и, воспрянув духом,","28":"Израиль сказал: «Довольно! Так Иосиф, мой сын, жив?! Пойду, увижу его перед смертью!»"},"46":{"1":"Израиль собрал все свое добро и отправился в путь. Придя в Беэр – Шеву, он принес жертву Богу своего отца Исаака –","2":"и Бог позвал его в ночном видении: «Иаков, Иаков!» – «Да», – ответил Израиль.","3":"Бог сказал: «Я Бог, Бог отца твоего. Не бойся, иди в Египет: там Я произведу от тебя великий народ.","4":"Я Сам пойду с вами в Египет, Я Сам и выведу вас оттуда. Иосиф своею рукою закроет тебе глаза».","5":"И Иаков оставил Беэр – Шеву. На повозках, которые им дал фараон, сыны Израилевы везли Иакова, детей и женщин;","6":"они гнали перед собой свои стада и везли добро, что нажили в Ханаане. Так Иаков вместе со всем своим потомством переселился в Египет:","7":"сыновей, внуков, дочерей, внучек – весь свой род он привел в Египет.","8":"Вот имена сынов Израилевых, переселившихся в Египет. Иаков и его сыновья. Первенец Иакова – Рувим.","9":"Сыновья Рувима: Енох, Паллу, Хецрон и Карми .","10":"Сыновья Симеона: Иемуэл, Ямин, Охад, Яхин, Цохар и Саул, сын ханаанеянки.","11":"Сыновья Левия: Гершон, Кехат и Мерари .","12":"Сыновья Иуды: Эр, Онан, Шела, Парец и Зерах. Эр и Онан умерли еще в Ханаане, а у Пареца родились сыновья Хецрон и Хамул.","13":"Сыновья Иссахара: Тола, Пувва, Иов и Шимрон.","14":"Сыновья Завулона: Серед, Элон и Яхлеэл.","15":"Это сыновья Иакова от Лии, родившиеся в Паддан – Араме, как и его дочь Дина. Всего, с сыновьями и дочерьми, – тридцать три человека.","16":"Сыновья Гада: Цифион, Хагги, Шуни, Эцбон, Эри, Ароди, Арели .","17":"Сыновья Асира: Имна, Ишва, Ишви и Берна. Их сестра – Серах. Сыновья Берии: Хевер и Малкиэл.","18":"Это потомки Иакова от Зелфы, которую Лаван дал в служанки своей дочери Лии, – шестнадцать человек.","19":"Сыновья Иакова от Рахили: Иосиф и Вениамин.","20":"В Египте Аснат, дочь гелиопольского жреца ПотиПеры, родила Иосифу сыновей Манассию и Ефрема.","21":"Сыновья Вениамина: Бела, Бехер, Ашбе л , Гера, Нааман, Эхи, Рош, Муппим, Хуппим и Ард.","22":"Это потомки Иакова от Рахили – четырнадцать человек.","23":"Сыновья Дана: Хушим.","24":"Сыновья Неффалима: Яхцеэл, Гуни, Иецер и Шиллем.","25":"Это потомки Иакова от Баллы, которую Лаван дал в служанки своей дочери Рахили, – семь человек.","26":"Общее число пришедших в Египет с Иаковом – его прямые потомки, не считая снох, – шестьдесят шесть человек.","27":"У Иосифа в Египте еще до этого родились двое. Всего род Иакова, переселившийся в Египет, состоял из семидесяти человек.","28":"А Иуду, меж тем, Иаков послал вперед, к Иосифу, чтобы Иосиф встречал их в Гошене. Они пришли в Гошен.","29":"Иосиф велел запрячь свою колесницу и поехал в Гошен, навстречу своему отцу Израилю. Он предстал перед отцом, обнял его и долго плакал в его объятиях.","30":"И промолвил Израиль: «Теперь, когда я увидел тебя живым, мне можно и умереть».","31":"Иосиф сказал своим братьям и всему своему роду: «Я иду сказать фараону, что ко мне из Ханаана пришли братья и весь мой род,","32":"что они пастухи, пасут овец, что привели с собой скот, мелкий и крупный, и привезли свое добро.","33":"А вы, когда фараон спросит, чем вы занимаетесь,","34":"отвечайте так: „Мы, рабы твои, пастухи с детства, как и отцы наши\". Тогда вас оставят в земле Гошен, потому что всех, кто пасет овец, египтяне считают оскверненными»."},"47":{"1":"Придя к фараону, Иосиф сказал: «Пришли из Ханаана мой отец и мои братья, вместе со стадами скота, мелкого и крупного, и со своим добром. Сейчас они в земле Тошен».","2":"Иосиф представил фараону пятерых из братьев.","3":"Фараон спросил, чем они занимаются, и те отвечали: «Мы, рабы твои, пасем овец, как и отцы наши».","4":"И еще сказали: «Мы пришли в эту землю как переселенцы. Нам, рабам твоим, негде пасти скот, ведь в Ханаане сейчас сильный голод. Позволь нам, рабам твоим, поселиться в земле Гошен».","5":"Фараон сказал Иосифу: «К тебе пришли отец и братья –","6":"так посели их в лучших краях нашей земли: вся страна египетская перед тобою. Пусть живут в земле Гошен. И если ты знаешь среди них подходящих людей, то поставь их смотреть за моими стадами».","7":"Затем Иосиф представил фараону своего отца Иакова. Иаков благословил фараона,","8":"и тот спросил: «Сколько же тебе лет?» –","9":"«Сто тридцать лет я прожил на свете, – отвечал Иаков. – Это немного, и трудными были эти годы. Им не сравниться с годами, которые прожили на свете мои прародители».","10":"И, вновь благословив фараона, Иаков удалился.","11":"Иосиф, как и повелел ему фараон, поселил отца и братьев в лучшем краю Египта, в области Раамсес, и наделил их там землей.","12":"И отцу, и братьям, и всему своему роду Иосиф выдавал зерно, каждому по числу детей в его семье.","13":"А в стране уже не осталось зерна – так силен был голод, поразивший и Египет и Ханаан.","14":"Продавая зерно их жителям, Иосиф собрал в казну фараона все серебро, какое только было в земле египетской и в земле ханаанской.","15":"Когда ни в Египте ни в Ханаане серебра уже не осталось, египтяне пришли к Иосифу и сказали: «Дай нам зерна! Неужели нам умирать у тебя на глазах? Серебро кончилось». –","16":"«Если кончилось серебро, – отвечал Иосиф, – то приводите сюда свой скот, буду менять зерно на скот».","17":"Они пригнали свои стада, и Иосиф стал менять зерно на скот: на лошадей, овец, коз, коров, ослов. В том году он давал им зерно в обмен на скот,","18":"а на следующий они пришли к нему с такими словами: «Не скрыть нам от тебя, господин наш, что и серебро наше, и скот наш – все к тебе перешло. Нечего нам тебе предложить, кроме наших тел и нашей земли.","19":"Неужели нам погибать у тебя на глазах, вместе с нашей землей? Возьми и нас, и наши земли в обмен на зерно – и мы будем, вместе с нашей землей, рабами фараона. Только дай семян, чтобы нам остаться в живых, а земле не прийти в запустение».","20":"Так Иосиф скупил для фараона все земли в Египте. Египтяне, все до одного, продали ему свои поля – так силен был голод. Вся земля стала собственностью фараона,","21":"а египтян по всей стране – от края до края – Иосиф сделал рабами фараона.","22":"Только земли жрецов Иосиф не смог скупить – жрецы были у фараона на содержании и за счет этого кормились, а потому и не стали продавать свои земли.","23":"Иосиф сказал египтянам: «Теперь, когда я купил для фараона и ваши поля, и вас самих, возьмите семена и засейте землю.","24":"Отныне пятую часть урожая вы будете отдавать фараону, а четыре пятых оставлять на семена и на пропитание – себе, домашним и детям».","25":"Египтяне отвечали: «Ты спас нам жизнь! Ты милостив к нам, господин наш. Отныне мы рабы фараона».","26":"Закон, установленный Иосифом, соблюдается в Египте и поныне: фараону отдают пятую часть урожая. Только земли жрецов не перешли к фараону.","27":"Израильтяне поселились в Египте, в земле Гошен. Там они владели землями, там стали они плодовиты и многочисленны.","28":"Семнадцать лет провел Иаков в Египте, а всего он прожил сто сорок семь лет.","29":"Когда пришла ему пора умирать, он позвал Иосифа и сказал: «Окажи милость, поклянись мне, коснувшись бедра моего, что ты не забудешь выполнить мою просьбу: не хорони меня в Египте!","30":"Когда я отойду к предкам, то увези меня из Египта и похорони меня в усыпальнице моих предков». – «Я сделаю, как ты сказал», – отвечал Иосиф.","31":"«Поклянись», – сказал Иаков. Иосиф поклялся, и Иаков, лежавший на постели, склонил голову."},"48":{"1":"Некоторое время спустя, узнав, что отец болен, Иосиф привел к нему своих сыновей, Манассию и Ефрема.","2":"«Пришел твой сын, Иосиф», – сказали Иакову. Тот собрался с силами, сел на постели","3":"и обратился к Иосифу: «Некогда, в Лузе, в земле ханаанской, мне явился Бог Всесильный. Он благословил меня","4":"и сказал: „Я сделаю твой род плодовитым и многочисленным, произведу от тебя множество народов, а эту землю навеки отдам твоим потомкам\". –","5":"И вот, теперь, – сказал Иаков Иосифу, – я усыновляю обоих твоих сыновей, которые родились в Египте до моего прихода. Теперь Ефрем и Манассия будут моими, наравне с Рувимом и Симеоном.","6":"А сыновья, родившиеся у тебя после, – те твои, но причтены будут к родам своих братьев и получат наследство из их доли.","7":"А моя Рахиль, – сказал Иаков, – умерла в пути, когда я возвращался из Паддана, в Ханаане, неподалеку от Эфраты. Там я и похоронил ее – у дороги на Эфрату (что ныне называется Вифлеем)…»","8":"И, посмотрев на детей Иосифа, Израиль спросил его: «Кто это?» –","9":"«Это мои сыновья, – ответил Иосиф, – которых здесь даровал мне Бог». – «Подведи их ко мне, – сказал Израиль, – чтобы я их благословил».","10":"Старость помрачила глаза Израиля – он ничего не видел. Иосиф подвел к нему детей; Израиль расцеловал их, обнял","11":"и сказал Иосифу: «Я и тебя – то уж не надеялся увидеть, а вот, Бог дал мне увидеть и твоих детей».","12":"Иосиф взял своих детей – они были на коленях у Израиля – и поклонился отцу до земли.","13":"Когда Иосиф подвел своих сыновей к Израилю, то Ефрем был справа от него (от Израиля по левую сторону), а Манассия слева (от Израиля по правую сторону).","14":"Но Израиль возложил правую руку на голову Ефрема, младшего, а левую – на голову Манассии, старшего, так что руки его скрестились.","15":"И благословил Израиль Иосифа такими словами: «Бог – пред лицом Его жили отцы мои, Авраам и Исаак! – Бог, пастырь мой всегда и доныне,","16":"Ангел, избавлявший меня от всякого зла, – да благословит отроков! К роду моему они принадлежат, к роду отцов моих – Авраама и Исаака. Многочисленно будет на земле их потомство».","17":"Увидел Иосиф, что свою правую руку отец возложил на Ефрема, и, приняв это за ошибку, взял руку отца, чтобы переложить ее с Ефрема на Манассию.","18":"«Не так, отец, – сказал Иосиф. – Вот первенец, возложи на него правую руку». –","19":"«Я знаю, – ответил Израиль, – я знаю, сынок. От него тоже произойдет великий народ. И все же младший брат превзойдет его и даст начало множеству племен».","20":"Вот слова, которыми Израиль благословил их в тот день: «Благословением вы станете для израильтян. Они будут говорить, благословляя друг друга: „Да сделает тебя Бог подобным Ефрему и Манассии!\"» Так поставил он Ефрема впереди Манассии.","21":"Потом Израиль сказал Иосифу: «Я скоро умру. Но Бог будет с вами и вернет вас в землю ваших отцов.","22":"А тебе я даю горный кряж – Шехем: ты будешь выше, чем братья. Я отбил его у амореев мечом и стрелами»."},"49":{"1":"Созвал Иаков своих сыновей: «Соберитесь: я скажу вам, что вас ждет в грядущем.","2":"Сойдитесь, слушайте, сыны Иакова, – Израиля слушайте, отца своего!","3":"Рувим, мой первенец, моя мощь, первый плод моей силы мужской, всех он выше – само могущество!","4":"Безудержный, как воды, больше первым не будешь ты, раз возлег на постель отца – попрал, осквернил мое ложе!","5":"Симеон и Левий, братья, чьи ножи – оружье жестокости!","6":"Не участник я их замыслов, к их ватаге я непричастен. Прогневаются – убивают людей, потешаются – калечат быков.","7":"Проклят гнев их, что так жесток, и их ярость, что столь свирепа! Средь сынов Иакова разметаю их, рассею средь сынов Израилевых!","8":"Иуда, братья восхвалят тебя! Твоя рука – на загривке врагов, пред тобою склонятся братья твои.","9":"Ты как лев молодой, Иуда, – над добычей вздымаешься, сын мой. Словно лев в засаде к земле припал – кто осмелится льва потревожить?","10":"Не выпадет жезл из рук Иуды, правителя посох у ног его. Время придет – он получит дань и народы ему покорятся.","11":"Для осла у него привязь – виноградная ветвь, винная лоза – ослятам привязь. Одежды свои он полощет в вине, свои ризы – в крови виноградной.","12":"А глаза его – темнее вина, молока белее зубы его.","13":"Завулон будет жить на морском берегу, где корабли пристают. И граница его – у Сидона.","14":"Иссахар – это крепкий осел, что разлегся среди вьюков;","15":"он увидал, что покой хорош, что прекрасна эта земля, и подставил спину под ношу, подневольным стал.","16":"Дан будет править народом своим: это тоже одно из племен Израиля.","17":"Да будет Дан змеей на дороге, ядовитой змеей при пути. Ужалит коня в ногу – и всадник падет навзничь.","18":"(Спаси, Господи! На Тебя надеюсь!)","19":"Налетят на Гада грабители – по пятам полетит он грабить их.","20":"У Асира обильна пища, царские яства поставляет он.","21":"Неффалим – это вольная лань, что рожает прекрасных детенышей.","22":"Иосиф – лоза плодовитая, плодовитая лоза у источника. Ее ветви обвили стену.","23":"Нападали на него, враждовали с ним, воевали с ним искусные лучники.","24":"Но тугим непрестанно был лук его, ведь источник силы рукам его – руки Крепкого, Бога Иаковлева, и имя Пастыря, Скалы Израиля!","25":"Он – твой отчий Бог, Он поможет тебе, Он – Всесильный, Он благословит тебя. Благословенья высокого неба, благословения глубокой бездны, благословенья сосцов и утробы,","26":"благословенья цветов и колосьев, благословения древних гор, щедрый дар вечных холмов – главу Иосифа да осенят – темя избранника средь братьев.","27":"Вениамин – это хищный волк: утром жертву свою грызет, вечером разрывает добычу».","28":"Таковы двенадцать израильских племен – и благословения, которые им дал отец. Каждому племени – свое благословение.","29":"Иаков сказал сыновьям: «Скоро мне уходить к предкам. Похороните меня рядом с моими предками, в пещере, что на поле Эфрона – хетта.","30":"Эта пещера – на поле Махпела, рядом с Мамре, в земле ханаанской, а поле Авраам купил у Эфрона – хетта как место для погребения.","31":"Там похоронены и Авраам с Саррой, и Исаак с Ревеккой, там я и Лию похоронил.","32":"И поле, и пещера, что на нем, куплены у хеттов».","33":"Дав сыновьям такой наказ, Иаков лег на постель и скончался, и отошел к предкам."},"50":{"1":"Иосиф припал к телу отца и, рыдая, целовал лицо усопшего.","2":"Своим рабам – врачам он велел набальзамировать тело Израиля.","3":"Сорок дней, как положено, врачи бальзамировали тело, и семьдесят дней египтяне оплакивали усопшего.","4":"Когда время траура кончилось, Иосиф попросил приближенных фараона: «Сделайте милость, скажите фараону,","5":"что мой отец взял с меня клятву: когда он умрет, я должен похоронить его в Ханаане, в усыпальнице, которую он заранее приготовил для себя. Я прошу позволения пойти и похоронить отца – а потом вернусь».","6":"И фараон разрешил: «Иди и похорони отца. Выполни клятву».","7":"Иосиф отправился хоронить отца, и с ним пошли все вельможи фараона, и все старшие сановники, и все старейшины земли египетской,","8":"и вся семья Иосифа, и все его братья, и весь его род – в земле Гошен остались только их дети и скот.","9":"И колесницы сопровождали его, и конница, и великое множество народа.","10":"Дойдя до Горен – Атада, что за Иорданом, они подняли там великий и горький плач – семь дней оплакивали они Иосифова отца.","11":"Ханаанеи, жившие в той земле, увидели траур в Горен – Атаде и воскликнули: «Как горько плачут египтяне!» (Потому – то и называется это место за Иорданом Авел – Мицраим.)","12":"Сыновья выполнили волю отца:","13":"принесли его тело в Ханаан и похоронили в пещере на поле Махпела, что некогда было куплено Авраамом у Эфрона – хетта как место для погребения – неподалеку от Мамре.","14":"После похорон Иосиф, его братья и все сопровождавшие вернулись в Египет.","15":"Теперь, после смерти отца, братья Иосифа задумались: «А что если Иосиф по – прежнему зол на нас и захочет отплатить за горе, которое мы ему причинили?»","16":"И они велели передать Иосифу: «Перед смертью отец завещал","17":"сказать тебе: „Прошу тебя, прости братьям их грех, их вину – то зло, которое они тебе причинили\". Так прости же нас, ведь мы рабы твоего отчего Бога!» Иосиф плакал, слушая эти слова.","18":"Братья пришли, простерлись перед ним на земле и сказали: «Отныне мы твои рабы!» –","19":"«Не бойтесь, – ответил Иосиф. – Разве я Бог?","20":"Вы замышляли против меня зло, а по Божьему промыслу оно обернулось добром: скольким людям это спасло жизнь!","21":"Не бойтесь. Я буду заботиться и о вас и о ваших детях». Этими словами он успокоил и утешил их.","22":"Так Иосиф поселился в Египте вместе со всем своим родом. Он прожил сто десять лет;","23":"ему довелось увидеть своих правнуков – внуков Ефрема – и взять на колени новорожденных детей Махира, сына Манассии.","24":"«Я скоро умру, – сказал Иосиф братьям. – Но настанет день, когда Бог вспомнит о вас и уведет вас отсюда в ту землю, которую Он поклялся отдать Аврааму, Исааку и Иакову».","25":"И Иосиф взял с сынов Израилевых клятву, что когда Бог вспомнит о них, они унесут с собой из Египта его останки.","26":"Иосиф умер в возрасте ста десяти лет. Его останки набальзамировали и положили в гроб, в Египте."}};
